/// State for the Sol/Astra/Luna reasoning-strength submenu opened from the
/// agent toolbar's `CodexModelTier` button. Modeled on `Submenu` and
/// `EditorLineContextMenu` -- a mouse- and keyboard-driven popup that owns
/// `App::mode` until a level is picked, Escape is pressed, or the pointer
/// clicks outside it.
pub struct AgentToolbarModelSubmenuState {
    pub pane_id: NodeId,
    pub tier_index: u8,
    pub area: Rect,
    pub selected_index: usize,
}

/// The delay `tick::on_tick` waits between stages of a
/// `PendingStagedKeystrokes` sequence. Confirmed live against `codex`:
/// typing `/model` opens its slash-command autocomplete, and an Enter
/// arriving before that popup has settled is consumed as "accept
/// completion" rather than "submit" -- the whole line lands in the chat
/// composer as text instead of opening the model picker. 280ms comfortably
/// clears that popup (tested reliable at 250ms) while staying imperceptible
/// as a menu action.
pub(crate) const STAGED_KEYSTROKE_DELAY: Duration = Duration::from_millis(280);

/// A multi-write PTY keystroke sequence in flight, drained one stage per
/// `STAGED_KEYSTROKE_DELAY` by `tick::on_tick`. Exists because Codex's
/// `/model` picker is an interactive, stateful TUI with no inline-argument
/// form (see `agent_toolbar::CodexModelTier`'s doc comment) -- switching
/// models means typing `/model`, waiting for its autocomplete to clear,
/// pressing Enter, then navigating its nested picker screens one digit at a
/// time. A new sequence starting while one is already in flight is ignored
/// rather than interleaved or replacing the old one mid-picker, which could
/// leave Codex's picker stuck on a screen the new sequence doesn't expect.
struct PendingStagedKeystrokes {
    pane_id: NodeId,
    stages: std::collections::VecDeque<Vec<u8>>,
    next_at: Instant,
    semantic_submission: bool,
    pane_identity: Option<std::sync::Arc<()>>,
}

/// State of a context menu: its tree target, screen position, and keyboard
/// or mouse selection. The renderer only reads this state; all effects stay
/// in `App`/`crate::keys`/`crate::mouse`.
struct TerminalContextBlueprint {
    key: crate::terminal_context_preparation::ContextKey,
    actions: Vec<TerminalContextAction>,
    screen_area: Rect,
}

pub struct ContextMenu {
    pub target: NodeId,
    pub area: Rect,
    pub actions: Vec<ContextMenuAction>,
    pub selected_index: usize,
    pub submenu: Option<Submenu>,
    /// Updated from the correlated repository-facts response while this menu
    /// remains open. Until then, worktree actions fail closed.
    pub worktree_unavailable_reason: Option<String>,
    pub hover_candidate: Option<(ContextMenuAction, Instant)>,
    unavailable_retention: Option<crate::connection::EventRetention>,
    unavailable_copies_retention: Option<crate::connection::EventRetention>,
}

impl ContextMenu {
    pub fn set_worktree_unavailable_reason(&mut self, reason: Option<String>) {
        self.worktree_unavailable_reason = reason;
        if let Some(submenu) = self.submenu.as_mut() {
            for item in &mut submenu.items {
                if matches!(
                    item.action,
                    SubmenuItemAction::AgentInNewWorktree(_)
                        | SubmenuItemAction::AgentInExistingWorktree(_)
                ) {
                    item.disabled_reason = self.worktree_unavailable_reason.clone();
                    item.disabled_reason_retention = None;
                }
            }
        }
        // Release previous copy credit only after all previous copies dropped.
        self.unavailable_retention = None;
        self.unavailable_copies_retention = None;
    }
    fn try_set_received_reason(
        &mut self,
        reason: Option<String>,
        owner: Option<&crate::connection::EventRetention>,
        copies: Option<&crate::connection::EventRetention>,
    ) -> Result<(), ilium_execution::RejectReason> {
        let copies = copies.cloned();
        if reason.is_some() && owner.is_some() && copies.is_none() {
            return Err(ilium_execution::RejectReason::InvalidCost);
        }
        self.set_worktree_unavailable_reason(reason);
        if self.worktree_unavailable_reason.is_some() {
            self.unavailable_retention = owner.cloned();
        }
        self.unavailable_copies_retention = copies;
        if let Some(submenu) = &mut self.submenu {
            for item in &mut submenu.items {
                if matches!(
                    item.action,
                    SubmenuItemAction::AgentInNewWorktree(_)
                        | SubmenuItemAction::AgentInExistingWorktree(_)
                ) {
                    item.disabled_reason_retention = self.unavailable_copies_retention.clone();
                }
            }
        }
        Ok(())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AgentDebugLogViewState {
    pub pane_id: NodeId,
    /// Explicit anchoring keeps Home/PageDown navigable without encoding the
    /// oldest position as an oversized offset from the newest event.
    pub scroll_position: AgentDebugLogScrollPosition,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AgentDebugLogScrollPosition {
    FromNewest(usize),
    FromOldest(usize),
}

impl AgentDebugLogViewState {
    pub fn scroll_older(&mut self, line_count: usize) {
        self.scroll_position = match self.scroll_position {
            AgentDebugLogScrollPosition::FromNewest(offset) => {
                AgentDebugLogScrollPosition::FromNewest(offset.saturating_add(line_count))
            }
            AgentDebugLogScrollPosition::FromOldest(offset) => {
                AgentDebugLogScrollPosition::FromOldest(offset.saturating_sub(line_count))
            }
        };
    }

    pub fn scroll_newer(&mut self, line_count: usize) {
        self.scroll_position = match self.scroll_position {
            AgentDebugLogScrollPosition::FromNewest(offset) => {
                AgentDebugLogScrollPosition::FromNewest(offset.saturating_sub(line_count))
            }
            AgentDebugLogScrollPosition::FromOldest(offset) => {
                AgentDebugLogScrollPosition::FromOldest(offset.saturating_add(line_count))
            }
        };
    }

    pub fn show_oldest(&mut self) {
        self.scroll_position = AgentDebugLogScrollPosition::FromOldest(0);
    }

    pub fn follow_newest(&mut self) {
        self.scroll_position = AgentDebugLogScrollPosition::FromNewest(0);
    }
}

/// Ephemeral viewer/export policy. The retained server journal stays complete;
/// operators can reveal animation evidence without restarting or recapturing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AgentDebugLogFilter {
    pub is_tree_panel_animation_resize_hidden: bool,
}

impl Default for AgentDebugLogFilter {
    fn default() -> Self {
        Self {
            is_tree_panel_animation_resize_hidden: true,
        }
    }
}

impl AgentDebugLogFilter {
    pub fn includes(self, entry: &ilium_ipc::AgentDebugEntry) -> bool {
        !self.is_tree_panel_animation_resize_hidden || !entry.is_tree_panel_animation_resize()
    }

    pub fn visible_entry_count(self, cache: &AgentDebugLogCache) -> usize {
        cache
            .log
            .entries
            .iter()
            .filter(|entry| self.includes(entry))
            .count()
    }

    pub fn hidden_entry_count(self, cache: &AgentDebugLogCache) -> usize {
        cache
            .log
            .entries
            .len()
            .saturating_sub(self.visible_entry_count(cache))
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct AgentDebugLogCache {
    /// Bounded, sequence-ordered mirror of the server-owned per-pane debug
    /// journal (`ilium_ipc::PaneDebugLog`, the exact schema and retention
    /// policy the server's own on-disk journal uses). Delegating to it here,
    /// instead of a raw `Vec`, means every insertion path -- the initial
    /// retained-history snapshot fetched via `GetPaneDebugLog`, and every
    /// subsequent `PaneDebugEntryAppended` broadcast for as long as the pane
    /// stays open -- is capped by the same `MAXIMUM_AGENT_DEBUG_ENTRIES` /
    /// `MAXIMUM_AGENT_DEBUG_BYTES` budget the server enforces, so a pane held
    /// open for the life of a long-running client session cannot grow this
    /// cache without bound (see `render_cache::apply`'s
    /// `PaneDebugEntryAppended` and `PaneDebugLogSnapshot` arms).
    pub log: ilium_ipc::PaneDebugLog,
    pub through_sequence: u64,
    /// Live broadcasts may populate the cache before the operator first opens
    /// the log. Only a replay snapshot proves that the retained prefix was
    /// fetched, so those broadcasts must not be mistaken for complete history.
    pub has_loaded_retained_history: bool,
    pub is_loading: bool,
}

