    /// Suspends the visible mode and opens one input-blocking child above it.
    /// The stack owns the complete parent state, so closing the child restores
    /// the exact selection, scroll position, and in-progress form values.
    pub(crate) fn push_modal(&mut self, mut modal: Mode) {
        if let Mode::SettingsHelp(state) = &mut modal {
            if state.topic_id == "AN-37" {
                // Help hides the preview and releases its host on the next draw.
                // Preserve the complete last report before changing modes.
                state.captured_scene_status = Some(
                    self.animation_row_context()
                        .scene_status
                        .unwrap_or_else(|| "OK".to_owned()),
                );
            }
        }
        let parent = std::mem::replace(&mut self.mode, modal);
        self.modal_stack.push(parent);
    }

    /// Opens a child when input dispatch has already moved its parent state
    /// out of `App::mode`. This is the normal keyboard/mouse handler path.
    pub(crate) fn push_modal_over(&mut self, parent: Mode, modal: Mode) {
        self.mode = parent;
        self.push_modal(modal);
    }

    pub(crate) fn begin_queue_delivery_dialog(&mut self, parent: Box<PromptQueueDialogState>) {
        match crate::value_dialog_host::ValueDialogHost::queue_delivery(&parent) {
            Ok(dialog) => self.push_modal_over(
                Mode::QueuePrompt(parent),
                Mode::ValueDialog(Box::new(dialog)),
            ),
            Err(error) => {
                self.status_message = Some(error);
                self.mode = Mode::QueuePrompt(parent);
            }
        }
    }

    pub(crate) fn finish_value_dialog(
        &mut self,
        mut host: Box<crate::value_dialog_host::ValueDialogHost>,
        outcome: crate::value_dialog::DialogOutcome,
    ) {
        use crate::value_dialog::DialogOutcome;
        let result = match outcome {
            DialogOutcome::Continue => {
                self.mode = Mode::ValueDialog(host);
                return;
            }
            DialogOutcome::Cancel => {
                self.pop_modal();
                return;
            }
            outcome @ (DialogOutcome::Choose(_) | DialogOutcome::CommitNumber(_)) => {
                if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::Animation(_)
                ) {
                    self.commit_animation_value_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::EditorLineDisplay { .. }
                ) {
                    self.commit_editor_line_display_dialog(&host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::Plugin(_)
                ) {
                    self.commit_plugin_value_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::Cost { .. }
                ) {
                    self.commit_cost_value_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::SettingsNumber { .. }
                        | crate::value_dialog_host::ValueTarget::DetectionNumber { .. }
                ) {
                    self.commit_settings_number_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::SettingsChoice { .. }
                ) {
                    self.commit_settings_choice_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::KeyboardPrefix { .. }
                ) {
                    self.commit_keyboard_prefix_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::SoundStudio { .. }
                ) {
                    self.commit_studio_number_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::OnboardingVoice { .. }
                ) {
                    self.commit_onboarding_voice_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::OnboardingInference { .. }
                ) {
                    self.commit_onboarding_inference_dialog(&mut host, &outcome)
                } else if matches!(
                    host.target,
                    crate::value_dialog_host::ValueTarget::AgentEffort { .. }
                ) {
                    self.commit_agent_effort_dialog(&host, &outcome)
                } else if let DialogOutcome::Choose(id) = outcome {
                    match self.modal_stack.last_mut() {
                        Some(Mode::Settings(parent)) => {
                            host.apply_icon_column_choice(parent, &id, self.layout.screen_area)
                        }
                        Some(Mode::WorktreeManager(parent)) => {
                            host.apply_prune_branch_choice(parent, &id)
                        }
                        Some(Mode::QueuePrompt(parent)) => host.apply_queue_choice(parent, &id),
                        Some(Mode::CreateBoard(parent)) => {
                            host.apply_board_storage_choice(parent, &id)
                        }
                        Some(Mode::CreateAgentFromLine(parent)) => {
                            host.apply_agent_from_line_provider(parent, &id)
                        }
                        Some(Mode::CreateAgentWorkspace(parent)) => {
                            host.apply_workspace_choice(parent, &id)
                        }
                        Some(Mode::TextTriggerDialog(parent)) => {
                            host.apply_trigger_scope_choice(parent, &id)
                        }
                        _ => Err("The parent form changed; reopen its options".into()),
                    }
                } else {
                    Err("This dialog target does not accept a number".into())
                }
            }
        };
        match result {
            Ok(()) if host.is_saving() => self.mode = Mode::ValueDialog(host),
            Ok(()) => self.pop_modal(),
            Err(error) => {
                host.reject(error);
                self.mode = Mode::ValueDialog(host);
            }
        }
    }

    pub(crate) fn begin_cost_value_dialog(&mut self, row: crate::cost_settings::CostRow) {
        let result = self
            .config_dir
            .clone()
            .ok_or_else(|| "The configuration directory is unavailable".to_owned())
            .and_then(|directory| {
                crate::value_dialog_host::ValueDialogHost::cost(&self.cost_settings, row, directory)
            });
        match result {
            Ok(host) => self.push_modal(Mode::ValueDialog(Box::new(host))),
            Err(error) => self.status_message = Some(error),
        }
    }

    fn commit_cost_value_dialog(
        &mut self,
        host: &mut crate::value_dialog_host::ValueDialogHost,
        outcome: &crate::value_dialog::DialogOutcome,
    ) -> Result<(), String> {
        let crate::value_dialog_host::ValueTarget::Cost { target, directory } = &host.target else {
            return Err("This is not a cost value dialog".into());
        };
        if host.is_saving() {
            return Err("The previous value is still being saved".into());
        }
        if self.config_dir.as_ref() != Some(directory) {
            return Err("The configuration destination changed; reopen this dialog".into());
        }
        let mut settings = self.cost_settings.clone();
        match outcome {
            crate::value_dialog::DialogOutcome::Choose(id) => {
                target.set_choice(&mut settings, id)?
            }
            crate::value_dialog::DialogOutcome::CommitNumber(text) => {
                target.set_number(&mut settings, text)?
            }
            _ => return Err("No cost value was submitted".into()),
        }
        let token = std::sync::Arc::new(());
        self.enqueue_configuration(
            directory.clone(),
            crate::filesystem::configuration::ConfigurationChange::Cost(settings.clone()),
            crate::filesystem::configurations::ConfigurationIntent::ValueDialog {
                token: std::sync::Arc::clone(&token),
            },
        )?;
        self.cost_settings = settings;
        host.begin_save(token);
        Ok(())
    }

    pub(crate) fn begin_animation_value_dialog(&mut self, row: usize) {
        use crate::animation_rows::AnimationRow;
        use crate::value_animation::{AnimationControlScope, AnimationControlTarget};
        if !self.prepare_animation_edit() {
            return;
        }
        let result = (|| {
            let model = self.animation_row_model();
            let scope = match model.row(row) {
                Some(AnimationRow::Common(_)) => AnimationControlScope::Common,
                Some(AnimationRow::SceneControl(_)) => AnimationControlScope::Scene,
                _ => return Err("This row does not offer a value dialog".into()),
            };
            let control = model
                .control(row)
                .cloned()
                .ok_or("Animation control is no longer available")?;
            let identity = format!(
                "{:?}/{:?}",
                self.animation_settings.kind,
                model.effective_kind()
            );
            let target = AnimationControlTarget::new_for_animation(
                self.animation_write_path()?,
                identity,
                scope,
                self.animation_settings.kind,
                control,
            )?;
            crate::value_dialog_host::ValueDialogHost::animation(target)
        })();
        match result {
            Ok(host) => self.push_modal(Mode::ValueDialog(Box::new(host))),
            Err(error) => self.status_message = Some(error),
        }
    }

    fn commit_animation_value_dialog(
        &mut self,
        host: &mut crate::value_dialog_host::ValueDialogHost,
        outcome: &crate::value_dialog::DialogOutcome,
    ) -> Result<(), String> {
        use crate::animation_rows::AnimationRow;
        use crate::value_animation::AnimationControlScope;
        use crate::value_dialog::DialogOutcome;
        let crate::value_dialog_host::ValueTarget::Animation(target) = &host.target else {
            return Err("This dialog is not an animation control".into());
        };
        if host.is_saving() {
            return Err("The previous value is still being saved".into());
        }
        if !self.prepare_animation_edit() {
            return Err("The animation is not ready for editing".into());
        }
        let model = self.animation_row_model();
        let row = (0..model.len())
            .find(|&row| match (target.scope(), model.row(row)) {
                (AnimationControlScope::Common, Some(AnimationRow::Common(id)))
                | (AnimationControlScope::Scene, Some(AnimationRow::SceneControl(id))) => {
                    *id == target.control_id()
                }
                _ => false,
            })
            .ok_or("The animation control disappeared; reopen its dialog")?;
        let current = model
            .control(row)
            .ok_or("The animation control is unavailable")?;
        let identity = format!(
            "{:?}/{:?}",
            self.animation_settings.kind,
            model.effective_kind()
        );
        let path = self.animation_write_path()?;
        let value = match outcome {
            DialogOutcome::Choose(id) => {
                target.choice(&path, &identity, target.scope(), current, id)?
            }
            DialogOutcome::CommitNumber(text) => {
                target.number(&path, &identity, target.scope(), current, text)?
            }
            _ => return Err("No animation value was submitted".into()),
        };
        let mut settings = self.animation_settings.clone();
        match target.scope() {
            AnimationControlScope::Common => {
                settings.set_common_control(target.control_id(), value)?
            }
            AnimationControlScope::Scene => {
                settings.set_scene_control(target.control_id(), value)?
            }
        };
        let token = std::sync::Arc::new(());
        self.enqueue_animation_settings_with_value(
            settings,
            None,
            Some(std::sync::Arc::clone(&token)),
        )?;
        host.begin_save(token);
        Ok(())
    }

    pub(crate) fn finish_value_dialog_save(
        &mut self,
        token: &std::sync::Arc<()>,
        mut result: Result<(), String>,
    ) {
        if result.is_ok()
            && matches!(&self.mode, Mode::ValueDialog(host)
            if matches!(&host.target, crate::value_dialog_host::ValueTarget::Plugin(target)
                if !target.binding_is_current(self)))
        {
            result = Err("Plugin binding changed while saving; reopen this dialog".into());
        }
        let success = result.is_ok();
        let error = result.as_ref().err().cloned();
        let Mode::ValueDialog(host) = &mut self.mode else {
            return;
        };
        if !host.finish_save(token, result) {
            return;
        }
        let api_port_saved = matches!(
            host.target,
            crate::value_dialog_host::ValueTarget::SettingsNumber {
                field: crate::value_settings::SettingsNumber::ApiPort,
                ..
            }
        );
        let session_recovery_saved = matches!(
            host.target,
            crate::value_dialog_host::ValueTarget::SettingsChoice {
                field: crate::value_settings_choice::SettingsChoice::SessionRecovery,
                ..
            }
        );
        if matches!(
            host.target,
            crate::value_dialog_host::ValueTarget::SettingsChoice {
                field: crate::value_settings_choice::SettingsChoice::GitDefaultWhere
                    | crate::value_settings_choice::SettingsChoice::GitDefaultBase
                    | crate::value_settings_choice::SettingsChoice::GitBranchLine
                    | crate::value_settings_choice::SettingsChoice::GitClosePolicy,
                ..
            }
        ) {
            self.git_settings_error = error.clone();
        }
        if success {
            self.pop_modal();
            if self.status_message.as_deref() == Some("Saving settings…") {
                self.status_message = Some(
                    if session_recovery_saved {
                        "Recovery policy saved; applies when the server next starts"
                    } else if api_port_saved {
                        "HTTP API port saved; restart the server to apply it"
                    } else {
                        "Settings saved to disk"
                    }
                    .into(),
                );
            }
        } else {
            self.status_message = error;
        }
    }

    /// Closes only the active child and restores its immediate parent. This
    /// deliberately supports arbitrary nesting rather than a settings-only
    /// return flag or a freshly reconstructed parent screen.
    pub(crate) fn pop_modal(&mut self) {
        self.mode = self.modal_stack.pop().unwrap_or(Mode::Normal);
    }

    /// Finishes a nested interaction whose successful action exits the whole
    /// flow, such as creating a board from a file-picker action menu.
    pub(crate) fn close_modal_flow(&mut self) {
        self.modal_stack.clear();
        self.mode = Mode::Normal;
    }

    pub fn queue_icon_semantic_search(&mut self, request: IconSearchRequest) {
        self.pending_icon_semantic_search = Some(request);
    }

    pub fn take_pending_icon_semantic_search(&mut self) -> Option<IconSearchRequest> {
        self.pending_icon_semantic_search.take()
    }

    pub fn apply_icon_semantic_search_event(&mut self, event: IconSemanticSearchEvent) {
        let Some(picker) = self.retained_icon_picker_mut() else {
            return;
        };
        match event {
            IconSemanticSearchEvent::Results { revision, results }
                if revision == picker.search_revision =>
            {
                picker.search_results = results;
                picker.search_status = IconPickerSearchStatus::Browse;
            }
            IconSemanticSearchEvent::Failed { revision, message }
                if revision == picker.search_revision =>
            {
                picker.search_status = IconPickerSearchStatus::Failed(message);
            }
            IconSemanticSearchEvent::Results { .. } | IconSemanticSearchEvent::Failed { .. } => {}
        }
    }

    /// Starts client-only row transitions ahead of `render_cache` swapping in
    /// `new_tree`. The first snapshot is deliberately adopted without motion:
    /// attaching to a restored session must not animate the whole tree as new.
    pub(crate) fn track_tree_snapshot_change(&mut self, new_tree: &Tree) {
        let now_offset_ms = self.started_at.elapsed().as_millis();
        self.track_tree_snapshot_change_at(new_tree, now_offset_ms);
    }

    /// Deterministic form of [`Self::track_tree_snapshot_change`] for focused
    /// tests of sequencing and pulse timing.
    fn track_tree_snapshot_change_at(&mut self, new_tree: &Tree, now_offset_ms: u128) {
        if !self.has_applied_first_snapshot {
            self.has_applied_first_snapshot = true;
            return;
        }

        let pulse_starts =
            self.tree_transitions
                .observe_snapshot_change(&self.tree, new_tree, now_offset_ms);
        for (node_id, pulse_started_offset_ms) in pulse_starts {
            self.recently_created
                .entry(node_id)
                .or_insert(pulse_started_offset_ms);
        }
    }

    /// Invalidates `tree_hit_test_cache` -- called once per
    /// `ServerEvent::TreeSnapshot` applied, regardless of whether the new
    /// tree actually differs from the old one (the server only ever sends
    /// a snapshot after an actual structural change or on attach, so
    /// treating every snapshot as a potential structural change costs at
    /// most one extra rebuild on an idle session, never a stale hit test).
    pub(crate) fn bump_tree_version(&mut self) {
        self.tree_version = self.tree_version.wrapping_add(1);
    }

    /// Drops creation-pulse bookkeeping for nodes no longer in the tree, or
    /// whose flash window has fully elapsed, keeping the map bounded
    /// independent of how often snapshots arrive.
    pub(crate) fn prune_recently_created(&mut self) {
        let now_offset = self.started_at.elapsed().as_millis();
        self.prune_recently_created_at(now_offset);
    }

    /// `prune_recently_created`'s logic with an explicit "now" offset, so
    /// tests can exercise flash-window expiry without a real clock.
    fn prune_recently_created_at(&mut self, now_offset_ms: u128) {
        let live_ids: HashSet<NodeId> = self.tree.all_ids().collect();
        self.recently_created.retain(|id, created_offset_ms| {
            live_ids.contains(id)
                && now_offset_ms.saturating_sub(*created_offset_ms)
                    < tree_ui::RECENTLY_CREATED_PULSE_MS
        });
    }

    /// Commit an already admitted nonterminal reply after its actor sideeffect.
    /// Moving the original guard is infallible and never reacquires capacity.
    pub(crate) fn enqueue_admitted_request(
        &mut self,
        request: crate::ipc_preparation::AdmittedRequest,
    ) {
        self.outbox.push(request);
    }

    pub(crate) fn take_admitted_outbound_requests(
        &mut self,
    ) -> Vec<crate::ipc_preparation::AdmittedRequest> {
        std::mem::take(&mut self.outbox)
    }

    #[cfg(test)]
    pub fn take_outbound_requests(&mut self) -> Vec<ClientRequest> {
        self.take_admitted_outbound_requests()
            .into_iter()
            .map(|request| {
                let (request, _retention) = request.into_parts();
                request
            })
            .collect()
    }

    /// Publish without awaiting a blocked socket. A refused FIFO head and
    /// every following request remain owned here for the next capacity wake.
    pub(crate) fn publish_outbound_requests(
        &mut self,
        sender: &crate::connection::RequestSender,
    ) -> Result<(), crate::connection::RequestPublicationClosed> {
        let requests = self.take_admitted_outbound_requests();
        let mut pending = requests.into_iter();
        while let Some(request) = pending.next() {
            let Err(error) = sender.try_send_admitted(request) else {
                continue;
            };
            let (request, is_closed) = match *error {
                tokio::sync::mpsc::error::TrySendError::Full(request) => (request, false),
                tokio::sync::mpsc::error::TrySendError::Closed(request) => (request, true),
            };
            self.outbox.push(request);
            self.outbox.extend(pending);
            return if is_closed {
                Err(crate::connection::RequestPublicationClosed)
            } else {
                Ok(())
            };
        }
        Ok(())
    }

    /// Detaches this connection cleanly and records how the CLI wrapper should
    /// proceed once the terminal has been restored by `TerminalGuard`.
    pub fn request_client_exit(&mut self, reason: ClientExitReason) -> bool {
        if self.queue_request(ClientRequest::Detach) {
            self.exit_reason = Some(reason);
            true
        } else {
            false
        }
    }

    /// Terminates the project-scoped server session. This is intentionally a
    /// separate leader action from [`request_client_exit`]: tmux/screen's
    /// detach leaves PTYs alive, while an explicit quit must not silently
    /// pretend to do the same thing.
    pub fn request_session_kill(&mut self) -> bool {
        if self.queue_request(ClientRequest::KillSession) {
            self.exit_reason = Some(ClientExitReason::Quit);
            true
        } else {
            false
        }
    }

    /// Drains every `PendingRetitleRequest` queued since the last drain,
    /// for `crate::run::dispatch_input_event` to actually spawn a worker
    /// for -- see that type's doc comment.
    /// Restores rejected originals without another screen/transcript capture.
    /// These lists retain the same per-pane/project intent identity and Loading
    /// state; rejection never claims that a provider started or completed.
    pub(crate) fn requeue_naming_request(
        &mut self,
        request: crate::naming_workers::NamingRequest,
    ) -> Result<(), Box<crate::naming_workers::NamingRequest>> {
        const MAX_RETRIES: usize = 16;
        const MAX_RETRY_BYTES: usize = 8 * 1024 * 1024;
        let bytes = self
            .pending_naming_retries
            .iter()
            .fold(request.retained_bytes(), |sum, item| {
                sum.saturating_add(item.retained_bytes())
            });
        if self.pending_naming_retries.len() >= MAX_RETRIES || bytes > MAX_RETRY_BYTES {
            return Err(Box::new(request));
        }
        self.pending_naming_retries.push(request);
        Ok(())
    }

    pub(crate) fn queue_exact_prompt_report(
        &mut self,
        result: crate::naming_workers::ExactAgentPromptTranscriptResult,
        hold: std::sync::Arc<crate::naming_workers::ExactSource>,
    ) {
        if let Some(last_prompt) = result.last_prompt {
            // One process-wide exact-source slot follows each admitted result.
            // Thus this FIFO plus every worker/channel owner is bounded to128.
            self.pending_exact_prompt_reports.push_back((
                ClientRequest::ReportAgentPromptFromTranscript {
                    pane_id: result.pane_id,
                    expected_session_id: result.session_id,
                    prompt_epoch: result.prompt_epoch,
                    last_prompt,
                },
                hold,
            ));
            self.collect_exact_prompt_reports();
        }
    }
    pub(crate) fn has_pending_exact_prompt_reports(&self) -> bool {
        !self.pending_exact_prompt_reports.is_empty()
    }
    pub(crate) fn unconfirmed_exact_prompt_reports(&self) -> usize {
        self.exact_prompt_reports_unflushed
            .saturating_add(self.pending_exact_prompt_reports.len())
    }
    pub(crate) fn confirm_exact_prompt_reports_flushed(&mut self) {
        self.exact_prompt_reports_unflushed = 0;
    }
    pub(crate) fn collect_exact_prompt_reports(&mut self) {
        while let Some((request, hold)) = self.pending_exact_prompt_reports.pop_front() {
            match self.try_queue_terminal_request(request) {
                Ok(()) => {
                    self.exact_prompt_reports_unflushed =
                        self.exact_prompt_reports_unflushed.saturating_add(1);
                    drop(hold);
                }
                Err(original) => {
                    self.pending_exact_prompt_reports
                        .push_front((*original, hold));
                    self.status_message =
                        Some("Exact transcript evidence waiting for outbound admission".into());
                    break;
                }
            }
        }
    }
    pub(crate) fn retain_exact_prompt_retry(
        &mut self,
        request: crate::naming_workers::ExactAgentPromptTranscriptRequest,
    ) {
        if self.pending_exact_prompt_retries.len() < 16 {
            self.pending_exact_prompt_retries.push(request);
            self.status_message = Some("Exact transcript recovery waiting for admission".into());
        } else {
            self.status_message=Some("Exact transcript recovery did not start: retry capacity reached; terminal input remains delivered".into());
        }
    }

    pub fn take_pending_retitle_requests(&mut self) -> Vec<PendingRetitleRequest> {
        std::mem::take(&mut self.pending_retitle_requests)
    }

    /// Drains every pane queued for a transcript-sourced last-prompt check
    /// since the last drain -- see `Self::pending_last_prompt_transcript_checks`.
    pub fn take_pending_last_prompt_transcript_checks(
        &mut self,
    ) -> Vec<PendingLastPromptTranscriptCheck> {
        std::mem::take(&mut self.pending_last_prompt_transcript_checks)
    }

    pub fn take_pending_exact_prompt_worker_cancellations(&mut self) -> Vec<NodeId> {
        std::mem::take(&mut self.pending_exact_prompt_worker_cancellations)
    }

    /// Locates the agent CLI's own session transcript for `pane_id`, for the
    /// last-prompt-from-transcript fallback. Deliberately independent of
    /// `crate::title_inference::session_title_input`'s retitle-specific
    /// gates (`titles_loading`, a user-specified title source): last-prompt
    /// tracking must keep working even while retitling is disabled, paused,
    /// or already in flight for this pane. `None` when no agent session ID
    /// has been resolved for this pane yet, matching the original feature
    /// request's "OR ... assuming we have the session id" phrasing -- live
    /// keystroke tracking remains the only source until then.
    pub fn last_prompt_transcript_context(
        &self,
        pane_id: NodeId,
    ) -> Option<(ilium_core::AgentClass, String, std::path::PathBuf)> {
        let session_id = self.agent_session_ids.get(&pane_id)?.clone();
        let node = self.tree.get(pane_id)?;
        let NodeKind::Pane { status, .. } = &node.kind else {
            return None;
        };
        let class = status.agent_state()?.class.clone();
        let pane_cwd = self
            .tree
            .pane_cwd(pane_id)
            .unwrap_or(&self.session_cwd)
            .to_path_buf();
        Some((class, session_id, pane_cwd))
    }

    /// Read-only history access can use a server-verified historical session.
    /// This is deliberately separate from the live transcript fallback worker:
    /// a stopped pane must never send a newly-read prompt back as live input.
    pub(crate) fn known_agent_history_context(
        &self,
        pane_id: NodeId,
    ) -> Option<(ilium_core::AgentClass, String, std::path::PathBuf)> {
        let node = self.tree.get(pane_id)?;
        let NodeKind::Pane { status, .. } = &node.kind else {
            return None;
        };
        let (class, session_id) = match status {
            PaneStatus::Agent(agent) => (
                agent.class.clone(),
                self.agent_session_ids.get(&pane_id)?.clone(),
            ),
            PaneStatus::AgentUnavailable(recovery) => {
                let session_id = recovery.session_id.as_ref()?.clone();
                if self
                    .agent_session_ids
                    .get(&pane_id)
                    .is_some_and(|client_id| client_id != &session_id)
                {
                    return None;
                }
                (recovery.process.class.clone(), session_id)
            }
            _ => return None,
        };
        let pane_cwd = self
            .tree
            .pane_cwd(pane_id)
            .unwrap_or(&self.session_cwd)
            .to_path_buf();
        Some((class, session_id, pane_cwd))
    }

    /// Resolves the paste-ready JSONL history path for one detected pane.
    ///
    /// The server owns session identity and the client owns clipboard access.
    /// Verifying the file here ensures a copied path belongs to this pane's
    /// current agent session and project.
    #[cfg(test)]
    fn history_file_path_for_pane(&self, pane_id: NodeId, home_dir: &Path) -> Option<PathBuf> {
        let (agent_class, session_id, project_path) = self.known_agent_history_context(pane_id)?;
        crate::agent_history_path::verified_jsonl_history_path(
            home_dir,
            &project_path,
            &agent_class,
            &session_id,
        )
    }

    pub(crate) fn queue_request(&mut self, request: ClientRequest) -> bool {
        if self.try_queue_terminal_request(request).is_err() {
            self.status_message=Some("Request rejected before admission: bounded request/input credits are unavailable; retry after pending work completes".into());
            return false;
        }
        true
    }
    pub(crate) fn try_queue_terminal_request(
        &mut self,
        request: ClientRequest,
    ) -> Result<(), Box<ClientRequest>> {
        let Some(client) = &self.outbound_admission else {
            return Err(Box::new(request));
        };
        let request = crate::ipc_preparation::admit_request(client, request)
            .map_err(|error| Box::new(error.value))?;
        if self.terminal_parsing.is_some() {
            let pane = match request.view() {
                ClientRequest::KeyInput { pane_id, .. }
                | ClientRequest::UserKeyInput { pane_id, .. }
                | ClientRequest::SubmitTerminalText { pane_id, .. }
                | ClientRequest::MouseInput { pane_id, .. } => Some(*pane_id),
                _ => None,
            };
            if let Some(id) = pane {
                if let Some(PaneRuntime::Terminal(view)) = self.panes.get(&id) {
                    return self
                        .terminal_input
                        .admit_admitted_request(id, view.identity.clone(), request)
                        .map_err(|request| {
                            let (request, _retention) = (*request).into_parts();
                            Box::new(request)
                        });
                }
            }
        }
        self.queue_terminal_request_after_barrier(request);
        Ok(())
    }

    fn queue_terminal_request_after_barrier(
        &mut self,
        request: crate::ipc_preparation::AdmittedRequest,
    ) {
        // Admission can precede a crash while the parser barrier is pending.
        // Recheck recovery here so retained mouse modes cannot receive input.
        if let ClientRequest::MouseInput { pane_id, .. } = request.view() {
            if self.tree.agent_recovery(*pane_id).is_some() {
                let pane_applied_ordinal =
                    self.panes.get(pane_id).and_then(|runtime| match runtime {
                        PaneRuntime::Terminal(view) => Some(view.applied_ordinal),
                        _ => None,
                    });
                tracing::warn!(
                    ?pane_id,
                    ?pane_applied_ordinal,
                    reason = "pane_entered_recovery",
                    boundary = "parser_barrier",
                    "admitted mouse input canceled before delivery"
                );
                self.status_message =
                    Some("Mouse input canceled: its pane entered recovery before delivery".into());
                return;
            }
        }
        match self.try_hold_terminal_request_after_baseline(request) {
            Ok(()) => {}
            Err(request) => self.publish_terminal_request_after_baseline(*request),
        }
    }

    pub(crate) fn publish_terminal_request_after_baseline(
        &mut self,
        request: crate::ipc_preparation::AdmittedRequest,
    ) {
        if let ClientRequest::MouseInput { pane_id, .. } = request.view() {
            if self.tree.agent_recovery(*pane_id).is_some() {
                let pane_applied_ordinal =
                    self.panes.get(pane_id).and_then(|runtime| match runtime {
                        PaneRuntime::Terminal(view) => Some(view.applied_ordinal),
                        _ => None,
                    });
                tracing::warn!(
                    ?pane_id,
                    ?pane_applied_ordinal,
                    reason = "pane_entered_recovery",
                    boundary = "baseline_publication",
                    "admitted mouse input canceled before delivery"
                );
                self.status_message =
                    Some("Mouse input canceled: its pane entered recovery before delivery".into());
                return;
            }
        }
        if let ClientRequest::UserKeyInput {
            pane_id,
            prompt_epoch: Some(epoch),
            ..
        } = request.view()
        {
            if self.is_detected_agent_pane(*pane_id)
                && !self
                    .pending_last_prompt_transcript_checks
                    .iter()
                    .any(|check| check.prompt_epoch == *epoch)
                && !self
                    .pending_exact_prompt_worker_cancellations
                    .contains(pane_id)
            {
                self.pending_exact_prompt_worker_cancellations
                    .push(*pane_id);
            }
        }
        let activity = match request.view() {
            ClientRequest::KeyInput { pane_id, bytes, .. }
            | ClientRequest::UserKeyInput { pane_id, bytes, .. }
                if !bytes.is_empty() =>
            {
                Some((
                    *pane_id,
                    TerminalActivityCause::KeyInputQueued {
                        byte_count: bytes.len(),
                    },
                ))
            }
            ClientRequest::SubmitTerminalText { pane_id, .. } => {
                Some((*pane_id, TerminalActivityCause::TerminalTextQueued))
            }
            _ => None,
        };
        self.outbox.push(request);
        if let Some((pane_id, cause)) = activity {
            self.record_plain_terminal_activity(pane_id, Instant::now(), cause);
        }
    }

    /// Writes raw bytes into a terminal pane's PTY, scrolling that pane's
    /// local view to the live tail first. Use for keystrokes and text that
    /// must remain unsubmitted; text plus Enter uses the semantic request.
    pub(crate) fn send_terminal_bytes(
        &mut self,
        pane_id: NodeId,
        bytes: Vec<u8>,
        submission: Option<PromptSubmissionSource>,
    ) -> Result<(), Box<ClientRequest>> {
        if let Some(PaneRuntime::Terminal(view)) = self.panes.get_mut(&pane_id) {
            view.scroll_to_bottom();
        }
        self.try_queue_terminal_request(ClientRequest::KeyInput {
            pane_id,
            bytes,
            submission,
        })
    }

    /// Direct user-origin bytes, including voice/control terminal actions.
    pub(crate) fn send_user_terminal_bytes(
        &mut self,
        pane_id: NodeId,
        bytes: Vec<u8>,
        submission: Option<PromptSubmissionSource>,
    ) -> Result<(), Box<ClientRequest>> {
        if let Some(PaneRuntime::Terminal(view)) = self.panes.get_mut(&pane_id) {
            view.scroll_to_bottom();
        }
        self.try_queue_terminal_request(ClientRequest::UserKeyInput {
            pane_id,
            bytes,
            submission,
            prompt_epoch: None,
        })
    }

    /// Queues one semantic text submission. The detached server inserts the
    /// text and later sends Enter under a pane-local input reservation.
    pub(crate) fn send_terminal_submission(
        &mut self,
        pane_id: NodeId,
        text: String,
        source: PromptSubmissionSource,
    ) -> Result<(), Box<ClientRequest>> {
        if let Some(PaneRuntime::Terminal(view)) = self.panes.get_mut(&pane_id) {
            view.scroll_to_bottom();
        }
        self.try_queue_terminal_request(ClientRequest::SubmitTerminalText {
            pane_id,
            text,
            source,
        })
    }

    /// Reports one successful editor/board mutation to the server-owned
    /// revision stream. The server response, not this optimistic request,
    /// advances the durable tree revision for every attached client.
    pub(crate) fn record_client_node_activity(&mut self, node_id: NodeId) {
        self.queue_request(ClientRequest::RecordNodeActivity { node_id });
    }

    /// Applies one authoritative activity revision. The two persisted
    /// checkpoints remain untouched: server focus and restructure events
    /// advance them independently.
    pub(crate) fn apply_node_activity(&mut self, node_id: NodeId, activity_revision: u64) {
        let _ = self
            .tree
            .merge_node_activity_revision(node_id, activity_revision);
    }

    /// Applies the exact revision acknowledged by a server-owned focus
    /// transition. A later activity event may arrive first on the broadcast
    /// channel, so this never rewinds `activity_revision`.
    pub(crate) fn apply_node_focus_checkpoint(&mut self, node_id: NodeId, activity_revision: u64) {
        let _ = self
            .tree
            .merge_node_focus_checkpoint(node_id, activity_revision);
    }

    /// Optimistically acknowledges the currently cached revision for an
    /// immediate visual response; the server broadcasts the authoritative
    /// checkpoint to every attachment and persists it.
    fn acknowledge_local_focus_activity(&mut self, node_id: NodeId) {
        let _ = self.tree.mark_node_focused(node_id);
    }

    /// Records a live-output edge only when parsed visible text actually
    /// changed. `TerminalView` owns the allocation-free fingerprint check and
    /// captures bounded row evidence only for changed screens.
    pub(crate) fn record_terminal_screen_change(
        &mut self,
        pane_id: NodeId,
        evidence: Option<VisibleTextEvidence>,
    ) {
        let Some(evidence) = evidence else {
            return;
        };
        self.record_plain_terminal_activity(
            pane_id,
            Instant::now(),
            TerminalActivityCause::VisibleTextChanged(evidence),
        );
    }

    /// Starts or refreshes activity only for an ordinary PTY-backed terminal.
    /// Detected agents retain their existing provider/activity indicators.
    fn record_plain_terminal_activity(
        &mut self,
        pane_id: NodeId,
        now: Instant,
        cause: TerminalActivityCause,
    ) {
        let is_plain_terminal = self.tree.get(pane_id).is_some_and(|node| {
            matches!(
                node.kind,
                NodeKind::Pane {
                    content: PaneContentKind::Terminal,
                    status: PaneStatus::PlainShell,
                    ..
                }
            )
        });

        if !is_plain_terminal {
            return;
        }

        let elapsed_ms = now.saturating_duration_since(self.started_at).as_millis();
        self.terminal_activity
            .record_with_cause(pane_id, elapsed_ms, cause);
    }

    pub fn active_pane_id(&self) -> Option<NodeId> {
        self.right_panel_target.active_pane_id()
    }

    pub(crate) fn focused_pane_id(&self) -> Option<NodeId> {
        matches!(self.focus, FocusTarget::Pane)
            .then(|| self.active_pane_id())
            .flatten()
    }

    pub fn displayed_pane_ids(&self) -> Vec<NodeId> {
        self.displayed_pane_slots().into_iter().flatten().collect()
    }

    /// Returns the right panel's bounded terminal set without allocating.
    /// Split views have a domain-enforced maximum of four children, so this
    /// fixed representation also serves the event loop's hot subscription
    /// comparison without a heap allocation on every output turn.
    pub(crate) fn displayed_pane_slots(&self) -> [Option<NodeId>; 4] {
        match self.right_panel_target {
            RightPanelTarget::Empty | RightPanelTarget::Chatroom { .. } => [None; 4],
            RightPanelTarget::Pane { pane_id } => [Some(pane_id), None, None, None],
            RightPanelTarget::SplitView { split_id, .. } => {
                let mut pane_slots = [None; 4];
                let Ok(children) = self.tree.children_of(split_id) else {
                    return pane_slots;
                };
                for (slot, pane_id) in pane_slots.iter_mut().zip(
                    children
                        .iter()
                        .copied()
                        .filter(|pane_id| self.tree.get(*pane_id).is_some_and(Node::is_pane)),
                ) {
                    *slot = Some(pane_id);
                }
                pane_slots
            }
        }
    }

    /// Whether one pane currently owns cells in the right panel. This avoids
    /// allocating the complete displayed-pane list on every PTY output event.
    pub(crate) fn is_pane_displayed(&self, pane_id: NodeId) -> bool {
        match self.right_panel_target {
            RightPanelTarget::Pane {
                pane_id: displayed_pane_id,
            } => displayed_pane_id == pane_id,
            RightPanelTarget::SplitView { split_id, .. } => {
                self.tree.parent_of(pane_id) == Some(split_id)
            }
            RightPanelTarget::Empty | RightPanelTarget::Chatroom { .. } => false,
        }
    }

    /// Moves focus around the panes currently visible in the right panel.
    /// This intentionally uses `displayed_pane_ids` rather than tree order:
    /// a leader action should navigate the active split, not jump into a
    /// hidden group elsewhere in the project tree.
    pub fn focus_visible_pane(&mut self, direction: i32) {
        let visible_panes = self.displayed_pane_ids();
        if visible_panes.is_empty() {
            return;
        }
        let current = self
            .active_pane_id()
            .and_then(|pane_id| visible_panes.iter().position(|id| *id == pane_id))
            .unwrap_or(0);
        let next =
            (current as i32 + direction.signum()).rem_euclid(visible_panes.len() as i32) as usize;
        self.focus_pane(visible_panes[next]);
    }

    /// Cycles among direct panes and split members in the group that owns the
    /// currently active/selected thing. Nested groups remain separate folders
    /// by design; [`Self::jump_to_group`] is the companion action that moves
    /// between them. This keeps the two actions orthogonal and makes their
    /// combined traversal cover the entire pane tree without flattening it.
    pub fn cycle_pane_in_current_group(&mut self, direction: i32) {
        let anchor = self.active_pane_id().or_else(|| self.selected_node_id());
        let Some(group_id) = anchor.and_then(|node_id| self.tree.containing_group(node_id)) else {
            self.status_message = Some("No current group contains a pane to cycle".to_string());
            return;
        };
        let pane_ids = self.tree.navigable_panes_in_group(group_id);
        if pane_ids.is_empty() {
            self.status_message = Some("This group has no panes to cycle".to_string());
            return;
        }
        let target_index = match self
            .active_pane_id()
            .and_then(|pane_id| pane_ids.iter().position(|candidate| *candidate == pane_id))
        {
            Some(current_index) => (current_index as i32 + direction.signum())
                .rem_euclid(pane_ids.len() as i32) as usize,
            None if direction < 0 => pane_ids.len() - 1,
            None => 0,
        };
        self.focus_pane(pane_ids[target_index]);
    }

    /// Jumps to the first pane in the next or previous non-empty group in
    /// visible tree order. A project is an ownership boundary, not a group,
    /// so this naturally traverses groups across projects while preserving
    /// their real nesting/order. Empty groups are skipped because no focusable
    /// "first thing" exists inside them.
    pub fn jump_to_group(&mut self, direction: i32) {
        let groups: Vec<NodeId> = self
            .tree
            .group_ids_in_tree_order()
            .into_iter()
            .filter(|group_id| !self.tree.navigable_panes_in_group(*group_id).is_empty())
            .collect();
        if groups.is_empty() {
            self.status_message = Some("No groups contain panes to jump to".to_string());
            return;
        }

        let anchor = self.active_pane_id().or_else(|| self.selected_node_id());
        let current_group = anchor.and_then(|node_id| self.tree.containing_group(node_id));
        let target_index = match current_group
            .and_then(|group_id| groups.iter().position(|candidate| *candidate == group_id))
        {
            Some(current_index) => {
                (current_index as i32 + direction.signum()).rem_euclid(groups.len() as i32) as usize
            }
            None if direction < 0 => groups.len() - 1,
            None => 0,
        };
        let target_group = groups[target_index];
        // `groups` was filtered with this exact helper immediately above, so
        // every target has a first pane unless an impossible in-memory tree
        // mutation interleaves inside this synchronous method.
        if let Some(pane_id) = self
            .tree
            .navigable_panes_in_group(target_group)
            .first()
            .copied()
        {
            self.focus_pane(pane_id);
        }
    }

    /// Focuses the nearest visible split member in a cardinal direction.
    /// The decision uses the shared viewport allocator, so rendering, mouse
    /// hit testing, and keyboard travel agree even for the four-pane grid.
    pub fn focus_visible_pane_in_direction(&mut self, horizontal: i32, vertical: i32) {
        let Some(active_pane_id) = self.active_pane_id() else {
            return;
        };
        let viewports = self.pane_viewports();
        let Some(active) = viewports
            .iter()
            .find(|viewport| viewport.pane_id == active_pane_id)
            .copied()
        else {
            return;
        };
        let active_x = i32::from(active.outer_area.x) + i32::from(active.outer_area.width) / 2;
        let active_y = i32::from(active.outer_area.y) + i32::from(active.outer_area.height) / 2;
        let target = viewports
            .into_iter()
            .filter(|viewport| viewport.pane_id != active_pane_id)
            .filter_map(|viewport| {
                let x = i32::from(viewport.outer_area.x) + i32::from(viewport.outer_area.width) / 2;
                let y =
                    i32::from(viewport.outer_area.y) + i32::from(viewport.outer_area.height) / 2;
                let delta_x = x - active_x;
                let delta_y = y - active_y;
                let is_in_direction = match (horizontal, vertical) {
                    (-1, 0) => delta_x < 0,
                    (1, 0) => delta_x > 0,
                    (0, -1) => delta_y < 0,
                    (0, 1) => delta_y > 0,
                    _ => false,
                };
                is_in_direction.then_some((viewport.pane_id, delta_x.abs() + delta_y.abs()))
            })
            .min_by_key(|(_, distance)| *distance)
            .map(|(pane_id, _)| pane_id);
        if let Some(pane_id) = target {
            self.focus_pane(pane_id);
        }
    }

    /// Applies one full viewport of local scrollback motion to the focused
    /// terminal. Editor panes are deliberately ignored: their native editor
    /// navigation retains ownership of its own scroll position.
    pub fn scroll_focused_terminal(&mut self, direction: i32) {
        let Some(pane_id) = self.active_pane_id() else {
            return;
        };
        let Some(PaneRuntime::Terminal(view)) = self.panes.get_mut(&pane_id) else {
            return;
        };
        let page_lines = self.last_known_pane_size.0.max(1);
        if direction < 0 {
            view.scroll_up(page_lines);
        } else {
            view.scroll_down(page_lines);
        }
    }

    pub fn pane_viewports(&self) -> Vec<PaneViewport> {
        let viewports = match self.right_panel_target {
            RightPanelTarget::Empty | RightPanelTarget::Chatroom { .. } => Vec::new(),
            RightPanelTarget::Pane { pane_id } => split_layout::allocate_viewports(
                self.layout.pane_area,
                SplitOrientation::Vertical,
                &[pane_id],
            ),
            RightPanelTarget::SplitView { split_id, .. } => {
                let orientation = self
                    .tree
                    .split_orientation(split_id)
                    .unwrap_or(SplitOrientation::Vertical);
                split_layout::allocate_viewports(
                    self.layout.pane_area,
                    orientation,
                    &self.displayed_pane_ids(),
                )
            }
        };
        viewports
            .into_iter()
            .map(|viewport| {
                let is_terminal = self.tree.get(viewport.pane_id).is_some_and(|node| {
                    matches!(
                        &node.kind,
                        NodeKind::Pane {
                            content: PaneContentKind::Terminal,
                            ..
                        }
                    )
                });
                if !is_terminal {
                    return viewport;
                }
                // Reserve before interaction: metadata changes only redraw these slots.
                let viewport = if self.ui_settings.agent_toolbar_enabled {
                    viewport.with_agent_toolbar_reserved()
                } else {
                    viewport
                };
                let viewport = if self.ui_settings.last_prompt_enabled {
                    // In a physically clipped pane, leave room for the progress
                    // gauge and a detail row as well as the terminal itself.
                    let minimum_progress_rows = if self.ui_settings.progress_monitor_enabled {
                        2.min(viewport.content_area.height.saturating_sub(2))
                    } else {
                        0
                    };
                    let prompt_rows = crate::last_prompt_banner::reserved_height(
                        self.ui_settings.last_prompt_max_lines.into(),
                    )
                    .min(
                        viewport
                            .content_area
                            .height
                            .saturating_sub(1 + minimum_progress_rows),
                    );
                    viewport.with_last_prompt_reserved(prompt_rows)
                } else {
                    viewport
                };
                if self.ui_settings.progress_monitor_enabled {
                    viewport.with_progress_reserved(crate::progress_bar::reserved_height(
                        self.ui_settings.progress_max_lines.into(),
                    ))
                } else {
                    viewport
                }
            })
            .collect()
    }

    /// Whether the already-reserved toolbar slot displays controls. Terminal
    /// geometry reserves this row before agent detection; this check only
    /// controls visibility. A detected agent or the retained latch keeps the
    /// controls visible after an agent exits, unless the user disables the
    /// toolbar. Checking live status also covers detection paths that have
    /// not populated the latch yet.
    pub fn shows_agent_toolbar(&self, pane_id: NodeId) -> bool {
        self.ui_settings.agent_toolbar_enabled
            && (self.is_known_agent_pane(pane_id)
                || self.agent_toolbar_latched_panes.contains(&pane_id))
    }

    /// The transcript fallback worker only observes a confirmed live agent.
    /// Historical prompt display is handled separately by recovery status.
    pub fn last_prompt_tracking_enabled(&self, pane_id: NodeId) -> bool {
        self.ui_settings.last_prompt_enabled && self.is_detected_agent_pane(pane_id)
    }

    /// Stopped agent recovery has priority over the pane-wide prompt cache,
    /// which might later describe shell input or an older exact submission.
    pub(crate) fn display_last_agent_prompt(&self, pane_id: NodeId) -> Option<&str> {
        let node = self.tree.get(pane_id)?;
        let NodeKind::Pane { status, .. } = &node.kind else {
            return None;
        };
        match status {
            PaneStatus::AgentUnavailable(recovery) => recovery.last_prompt.as_deref(),
            PaneStatus::Agent(_) => self.tree.last_prompt(pane_id),
            _ => None,
        }
    }

    /// Whether the fixed prompt slot displays recorded text. Hiding its text
    /// never changes terminal dimensions.
    pub fn shows_last_prompt_banner(&self, pane_id: NodeId) -> bool {
        self.ui_settings.last_prompt_enabled
            && self
                .display_last_agent_prompt(pane_id)
                .is_some_and(|text| !text.is_empty())
    }

    /// Whether the already-reserved progress slot displays a report: the user
    /// hasn't turned the feature off and the server has an active report for
    /// this pane. Unlike the toolbar/last-prompt banner, this is not gated
    /// on "detected agent" -- a progress monitor can be running in any
    /// terminal pane, agent or not (see `ilium-server`'s `progress_monitor`
    /// module doc). Gating on `ui_settings.progress_monitor_enabled` here
    /// too (not only server-side) means a pane whose footer was still
    /// showing at the instant the setting was toggled off disappears
    /// immediately rather than lingering until the server's own clearing
    /// broadcast arrives.
    pub fn shows_progress_footer(&self, pane_id: NodeId) -> bool {
        self.ui_settings.progress_monitor_enabled
            && crate::progress_display::footer_is_visible(
                self.tree.pane_progress(pane_id),
                self.ui_settings.completed_progress_hide_after_seconds,
                self.progress_display_now_unix_millis,
            )
    }

    /// Hides expired result text without resizing or mutating retained data.
    pub(crate) fn tick_completed_progress_display(&mut self, now_unix_millis: u64) -> bool {
        let previous = self
            .displayed_pane_ids()
            .into_iter()
            .map(|pane_id| (pane_id, self.shows_progress_footer(pane_id)))
            .collect::<Vec<_>>();
        self.progress_display_now_unix_millis = now_unix_millis;
        previous
            .into_iter()
            .any(|(pane_id, was_visible)| was_visible != self.shows_progress_footer(pane_id))
    }

    /// The provider driving `pane_id`'s toolbar buttons right now, or `None`
    /// when the pane's current status isn't a detected built-in agent (an
    /// `AgentClass::Other` custom signature, or a latched pane whose agent
    /// has since exited back to a plain shell). Only the provider-independent
    /// buttons (Stop/CopyScreen/Close) render in that case.
    pub fn agent_toolbar_provider(&self, pane_id: NodeId) -> Option<BuiltinAgentProvider> {
        let node = self.tree.get(pane_id)?;
        let NodeKind::Pane { status, .. } = &node.kind else {
            return None;
        };
        status.agent_state()?.class.provider()
    }

    pub fn pane_viewport(&self, pane_id: NodeId) -> Option<PaneViewport> {
        self.pane_viewports()
            .into_iter()
            .find(|viewport| viewport.pane_id == pane_id)
    }

    /// Reserve row/source metadata before widgets can consume one-time graphics
    /// effects. Busy admission leaves input and the previous emitted frame usable.
    pub(crate) fn admit_composition_metadata(&mut self) -> Result<bool, String> {
        // The previous ACK's DTO and its replacement can coexist within the
        // existing 70 MiB composition headroom. Refuse an impossible shape
        // explicitly, before any widget consumes one-time graphics effects.
        const MAX_METADATA_BYTES: usize = 32 * 1024 * 1024;
        let bytes = usize::from(self.layout.tree_area.height) * (64 * 1024) + 4096;
        if bytes > MAX_METADATA_BYTES {
            return Err(format!("Terminal tree geometry requires {bytes} metadata bytes; maximum per frame is {MAX_METADATA_BYTES}"));
        }
        match crate::execution::process_quota().reserve_external_storage(bytes) {
            Ok(hold) => {
                self.composition_metadata = Some(std::sync::Arc::new(hold));
                Ok(true)
            }
            Err(
                ilium_execution::RejectReason::Busy | ilium_execution::RejectReason::WorkerBytes,
            ) => Ok(false),
            Err(reason) => Err(format!(
                "Terminal composition metadata admission failed: {reason:?}"
            )),
        }
    }

    pub(crate) fn record_composed_tree_rows(&mut self, mut rows: crate::tree_ui::PaintedTreeRows) {
        rows.retain_metadata(self.composition_metadata.clone());
        self.composed_tree_rows = Some(std::sync::Arc::new(rows));
    }

    pub(crate) fn smart_copy_terminal_source(
        &self,
        pane_id: NodeId,
    ) -> Option<&crate::terminal_view::PaintedTerminal> {
        let source = self.smart_copy_source.as_ref()?;
        (self.smart_copy_session.as_ref().is_some_and(|session| session.pane_id == pane_id)
            && matches!(self.panes.get(&pane_id), Some(PaneRuntime::Terminal(view)) if std::sync::Arc::ptr_eq(&view.identity, &source.identity))).then_some(source)
    }

    pub(crate) fn selection_terminal_source(
        &self,
        pane_id: NodeId,
    ) -> Option<&crate::terminal_view::PaintedTerminal> {
        let (id, source) = self.terminal_selection_source.as_ref()?;
        (self.terminal_selection.is_some_and(|selection| selection.pane_id == pane_id)
            && *id == pane_id
            && matches!(self.panes.get(&pane_id), Some(PaneRuntime::Terminal(view)) if std::sync::Arc::ptr_eq(&view.identity, &source.identity)))
            .then_some(source)
    }

    pub(crate) fn emitted_terminal_source(
        &self,
        pane_id: NodeId,
    ) -> Option<crate::terminal_view::PaintedTerminal> {
        if let Some(geometry) = &self.emitted_geometry {
            let (_, source) = geometry
                .terminal_sources
                .iter()
                .find(|(id, _)| *id == pane_id)?;
            return matches!(self.panes.get(&pane_id), Some(PaneRuntime::Terminal(view))
                if std::sync::Arc::ptr_eq(&source.identity, &view.identity))
            .then(|| source.clone());
        }
        #[cfg(test)]
        if let Some(PaneRuntime::Terminal(view)) = self.panes.get(&pane_id) {
            return Some(view.painted_source());
        }
        None
    }

    pub(crate) fn emitted_status_tooltip(
        &self,
        node_id: NodeId,
        slot: crate::status_icons::StatusSlot,
    ) -> Option<&crate::status_icons::TooltipContent> {
        self.emitted_geometry
            .as_ref()?
            .tree_rows
            .as_ref()?
            .status_tooltip(node_id, slot)
    }
    pub(crate) fn emitted_worktree_tooltip(
        &self,
        node_id: NodeId,
    ) -> Option<&crate::status_icons::TooltipContent> {
        self.emitted_geometry
            .as_ref()?
            .tree_rows
            .as_ref()?
            .worktree_tooltip(node_id)
    }
    pub(crate) fn emitted_cost_card_target(
        &self,
    ) -> Option<(u16, &crate::tree_ui::PaintedRowValues)> {
        let (row, values) = self
            .emitted_geometry
            .as_ref()?
            .tree_rows
            .as_ref()?
            .cost_card_target(self.hovered_tree_node)?;
        self.tree.get(values.node_id).map(|_| (row, values))
    }

    pub(crate) fn emitted_tree_toolbar_at(&self, position: Position) -> Option<TreeToolbarAction> {
        if let Some(geometry) = &self.emitted_geometry {
            return geometry.tree_rows.as_ref()?.toolbar_at(position);
        }
        if cfg!(test) {
            return tree_ui::toolbar_action_at(self.layout.tree_area, position);
        }
        None
    }

    pub(crate) fn emitted_tree_action_at(
        &self,
        position: Position,
    ) -> Option<(TreeNodeHit, crate::tree_ui::TreeRowAction)> {
        if let Some(geometry) = &self.emitted_geometry {
            let (hit, action) = geometry.tree_rows.as_ref()?.action_at(position)?;
            return self.tree.get(hit.id).map(|_| (hit, action));
        }
        #[cfg(test)]
        if let Some(hit) = self.hovered_tree_node.filter(|hit| hit.line == 0) {
            return tree_ui::row_action_at(
                &self.tree,
                hit.id,
                self.layout.tree_area,
                hit.row,
                position,
                self.ui_settings.show_tree_row_management_controls,
            )
            .map(|action| (hit, action));
        }
        None
    }

    pub(crate) fn capture_emitted_geometry(&self, revision: u64) -> EmittedGeometry {
        EmittedGeometry {
            revision,
            terminal_sources: self.composed_terminal_sources.clone(),
            editor_sources: self.composed_editor_sources.clone(),
            tree_rows: self.composed_tree_rows.clone(),
            _metadata: self.composition_metadata.clone(),
            layout: self.layout,
            mode: std::mem::discriminant(&self.mode),
            viewports: self.pane_viewports(),
            terminal_identities: self
                .pane_viewports()
                .into_iter()
                .filter_map(|viewport| match self.panes.get(&viewport.pane_id) {
                    Some(PaneRuntime::Terminal(view)) => {
                        Some((viewport.pane_id, std::sync::Arc::clone(&view.identity)))
                    }
                    _ => None,
                })
                .collect(),
        }
    }

    /// Returns the press held by `handle_mouse_event` when its frame has now
    /// been acknowledged and the layout it targeted is still the live one.
    pub(crate) fn take_deferred_pointer_press(&mut self) -> Option<crossterm::event::MouseEvent> {
        let (event, layout) = self.deferred_pointer_press.take()?;
        (self.pointer_geometry_is_current() && layout == self.layout).then_some(event)
    }

    pub(crate) fn commit_emitted_geometry(&mut self, geometry: EmittedGeometry) -> bool {
        // The card reads acknowledged sources. Request one replacement paint
        // when its source changes, including the first acknowledged tree.
        // Buffer-only acknowledgements must not create a redraw feedback loop.
        let previous = self.emitted_cost_card_target().map(|(row, values)| {
            (
                row,
                values.node_id,
                values.cost_title.as_str(),
                values.cost_card.as_ref().map(std::sync::Arc::as_ptr),
            )
        });
        let next = geometry
            .tree_rows
            .as_ref()
            .and_then(|rows| rows.cost_card_target(self.hovered_tree_node))
            .filter(|(_, values)| self.tree.get(values.node_id).is_some())
            .map(|(row, values)| {
                (
                    row,
                    values.node_id,
                    values.cost_title.as_str(),
                    values.cost_card.as_ref().map(std::sync::Arc::as_ptr),
                )
            });
        let card_changed = previous != next;
        self.emitted_geometry = Some(geometry);
        card_changed
    }

    pub(crate) fn emitted_layout_revision(&self) -> Option<u64> {
        self.emitted_geometry
            .as_ref()
            .map(|geometry| geometry.revision)
    }

    /// Reject before input admission when the interaction surface has changed
    /// but its corresponding complete frame has not actually been emitted.
    pub(crate) fn pointer_geometry_is_current(&self) -> bool {
        self.emitted_geometry.as_ref().is_none_or(|geometry| {
            geometry.layout == self.layout
                && geometry.mode == std::mem::discriminant(&self.mode)
                && geometry.viewports == self.pane_viewports()
                && geometry
                    .terminal_identities
                    .iter()
                    .all(|(pane_id, identity)| {
                        matches!(self.panes.get(pane_id), Some(PaneRuntime::Terminal(view))
                        if std::sync::Arc::ptr_eq(identity, &view.identity))
                    })
        })
    }

    pub fn pane_viewport_at(&self, position: Position) -> Option<PaneViewport> {
        match &self.emitted_geometry {
            Some(geometry) => split_layout::viewport_at(&geometry.viewports, position),
            None => split_layout::viewport_at(&self.pane_viewports(), position),
        }
    }

    /// Returns the exact frozen-screen rectangle used by Smart Copy rendering
    /// and pointer hit-testing. A completed agent's acknowledgement row is
    /// presentation chrome, not part of the captured terminal screen.
    pub(crate) fn smart_copy_terminal_area(&self, pane_id: NodeId) -> Option<Rect> {
        let viewport = self.pane_viewport(pane_id)?;
        Some(
            self.completed_agent_close_action(viewport)
                .map_or(viewport.content_area, |action| action.terminal_area),
        )
    }

    /// Returns every currently actionable transfer across a visible split
    /// separator. A transfer is available only when both panes have live
    /// terminal runtimes, which includes ordinary shells and detected agents
    /// but excludes editors, boards, and still-loading pane placeholders.
    pub(crate) fn screen_transfers(&self) -> Vec<ScreenTransfer> {
        split_layout::adjacent_pane_directions(&self.pane_viewports())
            .into_iter()
            .filter(|transfer| {
                self.is_live_terminal_pane(transfer.source_pane_id)
                    && self.is_live_terminal_pane(transfer.destination_pane_id)
            })
            .map(|transfer| ScreenTransfer {
                source_pane_id: transfer.source_pane_id,
                destination_pane_id: transfer.destination_pane_id,
                direction: transfer.direction,
                control_area: transfer.control_area,
            })
            .collect()
    }

    /// Resolves a pointer position against the exact separator cells rendered
    /// as screen-transfer controls. The runtime eligibility above keeps a
    /// border next to an editor from behaving like a terminal paste target.
    pub(crate) fn screen_transfer_at(&self, position: Position) -> Option<ScreenTransfer> {
        self.screen_transfers()
            .into_iter()
            .find(|transfer| transfer.control_area.contains(position))
    }

    fn is_live_terminal_pane(&self, pane_id: NodeId) -> bool {
        matches!(self.panes.get(&pane_id), Some(PaneRuntime::Terminal(_)))
    }

    /// Returns the bottom-row close action for a pane whose detected agent
    /// has reached the durable `Done` state (the same state shown as a bell).
    pub(crate) fn completed_agent_close_action(
        &self,
        viewport: PaneViewport,
    ) -> Option<CompletedAgentCloseAction> {
        self.is_completed_agent_pane(viewport.pane_id)
            .then(|| completed_agent_action::layout(viewport))
            .flatten()
    }

    pub(crate) fn frozen_unfreeze_button(&self, viewport: PaneViewport) -> Option<Rect> {
        self.frozen_screens.contains_key(&viewport.pane_id).then(|| {
            let area = viewport.content_area;
            let height = area.height.min(7);
            let width = area.width.min(52);
            let dialog = Rect {
                x: area.x + area.width.saturating_sub(width) / 2,
                y: area.y + area.height.saturating_sub(height) / 2,
                width,
                height,
            };
            let button_width = dialog.width.min(22);
            Rect {
                x: dialog.x + dialog.width.saturating_sub(button_width) / 2,
                y: dialog.y + dialog.height.saturating_sub(2),
                width: button_width,
                height: 1,
            }
        })
    }

    /// Whether `pane_id` is a terminal agent that has finished its current
    /// turn and still needs acknowledgement rather than merely being idle.
    pub(crate) fn is_completed_agent_pane(&self, pane_id: NodeId) -> bool {
        matches!(
            self.tree.get(pane_id).map(|node| &node.kind),
            Some(NodeKind::Pane {
                content: PaneContentKind::Terminal,
                status: PaneStatus::Agent(agent),
                ..
            }) if agent.completion_unread
        )
    }

    pub fn reconcile_right_panel_target(&mut self) {
        self.right_panel_target = match self.right_panel_target.clone() {
            RightPanelTarget::Empty => RightPanelTarget::Empty,
            RightPanelTarget::Chatroom { project_id }
                if self.tree.get(project_id).is_some_and(Node::is_project)
                    && self
                        .tree
                        .get(project_id)
                        .and_then(Node::project_path)
                        .is_some_and(|_| self.chatroom_projects.contains(&project_id)) =>
            {
                RightPanelTarget::Chatroom { project_id }
            }
            RightPanelTarget::Pane { pane_id }
                if self.tree.get(pane_id).is_some_and(Node::is_pane) =>
            {
                match self.tree.parent_of(pane_id) {
                    Some(split_id) if self.tree.get(split_id).is_some_and(Node::is_split_view) => {
                        RightPanelTarget::SplitView {
                            split_id,
                            active_pane_id: Some(pane_id),
                        }
                    }
                    _ => RightPanelTarget::Pane { pane_id },
                }
            }
            RightPanelTarget::SplitView {
                split_id,
                active_pane_id,
            } if self.tree.get(split_id).is_some_and(Node::is_split_view) => {
                let active_pane_id = active_pane_id.filter(|pane_id| {
                    self.tree.parent_of(*pane_id) == Some(split_id)
                        && self.tree.get(*pane_id).is_some_and(Node::is_pane)
                });
                RightPanelTarget::SplitView {
                    split_id,
                    active_pane_id,
                }
            }
            _ => RightPanelTarget::Empty,
        };
    }

    /// Creates the file room and all provider-facing integration artifacts
    /// for one real project selected from its context menu.
    pub fn action_add_chatroom_to_project(&mut self, project_id: NodeId) {
        let Some(path) = self
            .tree
            .get(project_id)
            .filter(|node| node.is_project())
            .and_then(Node::project_path)
            .map(Path::to_path_buf)
        else {
            self.status_message = Some("That entry is not a project".into());
            return;
        };
        let intent = crate::filesystem::integrations::IntegrationIntent::AddRoom(
            crate::filesystem::integrations::RoomTarget {
                id: project_id,
                path,
            },
        );
        let _ = self.enqueue_integration(intent);
    }

    /// Selects a virtual room row and makes its file-backed feed the active
    /// right-panel surface without pretending it is a server-owned pane.
    pub fn show_chatroom(&mut self, project_id: NodeId) {
        if self
            .tree
            .get(project_id)
            .and_then(Node::project_path)
            .is_none()
        {
            return;
        }
        if !self.chatroom_projects.contains(&project_id) {
            self.status_message = Some("This project has no chatroom".to_string());
            return;
        }
        self.select_tree_path(vec![
            project_id,
            crate::tree_ui::chatroom_node_id(project_id),
        ]);
        self.right_panel_target = RightPanelTarget::Chatroom { project_id };
        if let Some(path) = self.tree.get(project_id).and_then(Node::project_path) {
            let state = self.chatrooms.entry(project_id).or_default();
            if state.draft.is_empty() {
                if let Some(index) = self
                    .failed_chatroom_appends
                    .iter()
                    .position(|(_, target, _)| target == path)
                {
                    state.draft = self.failed_chatroom_appends.remove(index).2;
                }
            }
        }
        self.focus = FocusTarget::Pane;
        self.refresh_chatroom(project_id);
    }

    /// Re-reads the visible project's room after an append or a low-frequency
    /// maintenance pass. Broken manual edits surface as a status message but
    /// retain the last readable messages instead of blanking the conversation.
    pub fn refresh_chatroom(&mut self, project_id: NodeId) -> bool {
        if self
            .tree
            .get(project_id)
            .and_then(Node::project_path)
            .is_none()
        {
            return false;
        }
        if let Err(error) = self.queue_integration_maintenance(false) {
            self.status_message = Some(error);
        }
        false
    }

    /// Checks every visible project at boot and during normal UI ticks. An
    /// existing room repairs missing provider hooks/guidance before its agents
    /// do further work; projects without rooms remain completely untouched.
    pub fn reconcile_chatroom_projects(&mut self) -> bool {
        let ids: HashSet<NodeId> = self.tree.project_ids().into_iter().collect();
        let before = self.chatroom_projects.len();
        self.chatroom_projects.retain(|id| ids.contains(id));
        self.chatrooms.retain(|id, _| ids.contains(id));
        if let Err(error) = self.queue_integration_maintenance(false) {
            self.status_message = Some(error);
        }
        let changed = before != self.chatroom_projects.len();
        if changed {
            self.bump_tree_version();
        }
        changed
    }

    /// Makes a structural project snapshot eligible for immediate chatroom
    /// discovery without coupling status-only tree version bumps to file I/O.
    pub(crate) fn request_chatroom_reconcile(&mut self) {
        self.next_chatroom_reconcile_at = Some(Instant::now());
    }

    /// Reconciles chatroom files only when their independent deadline is due.
    /// External writers remain visible within one second while high-frequency
    /// spinner ticks stay entirely in memory.
    pub fn tick_chatroom_projects(&mut self, now: Instant) -> bool {
        let Some(next_reconcile_at) = self.next_chatroom_reconcile_at else {
            return false;
        };
        if now < next_reconcile_at {
            return false;
        }
        let has_changed = self.reconcile_chatroom_projects();
        self.next_chatroom_reconcile_at = Some(now + CHATROOM_RECONCILE_INTERVAL);
        has_changed
    }

    /// Handles text entry directly in the room's composer. The user is the
    /// author of TUI messages; agents use the identical storage path through
    /// `ilium chat send`, so ordering remains serialized by the file lock.
    pub fn handle_chatroom_key(&mut self, key: crossterm::event::KeyEvent) {
        use crossterm::event::KeyCode;
        let RightPanelTarget::Chatroom { project_id } = self.right_panel_target else {
            return;
        };
        if !is_press(&key) {
            return;
        }
        match key.code {
            KeyCode::Esc => self.leave_pane_focus(),
            KeyCode::Up => self.scroll_chatroom_by(project_id, -1, 1),
            KeyCode::Down => self.scroll_chatroom_by(project_id, 1, 1),
            KeyCode::PageUp => {
                let page_lines = self
                    .chatroom_scroll_metrics(project_id)
                    .map(|metrics| metrics.visible_lines.max(1))
                    .unwrap_or(1);
                self.scroll_chatroom_by(project_id, -1, page_lines);
            }
            KeyCode::PageDown => {
                let page_lines = self
                    .chatroom_scroll_metrics(project_id)
                    .map(|metrics| metrics.visible_lines.max(1))
                    .unwrap_or(1);
                self.scroll_chatroom_by(project_id, 1, page_lines);
            }
            KeyCode::Home => self.scroll_chatroom_to_top(project_id),
            KeyCode::End => self.scroll_chatroom_to_bottom(project_id),
            KeyCode::Enter => {
                if self.failed_chatroom_appends.len() >= 32 {
                    self.status_message =
                        Some("Chatroom recovery capacity reached; draft retained".into());
                    return;
                }
                if self.chatrooms.get(&project_id).is_some_and(|state| {
                    state.draft.len() > 16 * 1024 || state.draft.chars().count() > 4000
                }) {
                    self.status_message = Some(
                        "Chatroom messages are limited to 4000 characters; draft retained".into(),
                    );
                    return;
                }
                let draft = self
                    .chatrooms
                    .get_mut(&project_id)
                    .map(|state| std::mem::take(&mut state.draft))
                    .unwrap_or_default();
                if draft.trim().is_empty() {
                    return;
                }
                let Some(project_root) = self
                    .tree
                    .get(project_id)
                    .and_then(Node::project_path)
                    .map(Path::to_path_buf)
                else {
                    // The draft was already taken out of the composer above;
                    // put it back so a project that vanished mid-composition
                    // (stale right-panel target) doesn't silently discard the
                    // user's typed message -- same recovery as a failed append.
                    if let Some(state) = self.chatrooms.get_mut(&project_id) {
                        state.draft = draft;
                    }
                    self.status_message =
                        Some("Could not send chatroom message: project is gone".to_string());
                    return;
                };
                let room = crate::filesystem::integrations::RoomTarget {
                    id: project_id,
                    path: project_root,
                };
                let intent = crate::filesystem::integrations::IntegrationIntent::Append {
                    room,
                    draft: draft.clone(),
                };
                if let Err(error) = self.enqueue_integration(intent) {
                    self.chatrooms.entry(project_id).or_default().draft = draft;
                    self.status_message = Some(format!("Could not send chatroom message: {error}"));
                }
            }
            KeyCode::Backspace => {
                if let Some(state) = self.chatrooms.get_mut(&project_id) {
                    state.draft.pop();
                }
            }
            KeyCode::Char(character)
                if !key
                    .modifiers
                    .contains(crossterm::event::KeyModifiers::CONTROL) =>
            {
                self.chatrooms
                    .entry(project_id)
                    .or_default()
                    .draft
                    .push(character);
            }
            _ => {}
        }
    }

    /// Routes wheel and scrollbar gestures for the active virtual room.
    ///
    /// Chatrooms do not own a server pane viewport, so this path deliberately
    /// uses `chatroom_ui`'s shared geometry instead of `handle_pane_mouse`.
    pub fn handle_chatroom_mouse(
        &mut self,
        mouse: crossterm::event::MouseEvent,
        position: Position,
    ) {
        use crossterm::event::{MouseButton, MouseEventKind};

        let RightPanelTarget::Chatroom { project_id } = self.right_panel_target else {
            return;
        };
        let room_layout = crate::chatroom_ui::layout(self.layout.pane_area);
        let metrics = self.chatroom_scroll_metrics(project_id);
        let is_dragging = self
            .chatrooms
            .get(&project_id)
            .is_some_and(|state| state.is_scrollbar_dragging);
        match mouse.kind {
            MouseEventKind::ScrollUp if room_layout.message_content_area.contains(position) => {
                self.scroll_chatroom_by(project_id, -1, 3);
            }
            MouseEventKind::ScrollDown if room_layout.message_content_area.contains(position) => {
                self.scroll_chatroom_by(project_id, 1, 3);
            }
            MouseEventKind::Down(MouseButton::Left)
                if metrics.is_some_and(|metrics| metrics.is_overflowing())
                    && room_layout.scrollbar_area.contains(position) =>
            {
                if let Some(state) = self.chatrooms.get_mut(&project_id) {
                    state.is_scrollbar_dragging = true;
                }
                if let Some(metrics) = metrics {
                    let top = crate::chatroom_ui::scrollbar_top_for_row(
                        room_layout.scrollbar_area,
                        metrics.maximum_top,
                        position.y,
                    );
                    self.set_chatroom_scroll_top(project_id, top, metrics.maximum_top);
                }
            }
            MouseEventKind::Drag(MouseButton::Left) if is_dragging => {
                if let Some(metrics) = metrics {
                    let top = crate::chatroom_ui::scrollbar_top_for_row(
                        room_layout.scrollbar_area,
                        metrics.maximum_top,
                        position.y,
                    );
                    self.set_chatroom_scroll_top(project_id, top, metrics.maximum_top);
                }
            }
            MouseEventKind::Up(MouseButton::Left) if is_dragging => {
                if let Some(metrics) = metrics {
                    let top = crate::chatroom_ui::scrollbar_top_for_row(
                        room_layout.scrollbar_area,
                        metrics.maximum_top,
                        position.y,
                    );
                    self.set_chatroom_scroll_top(project_id, top, metrics.maximum_top);
                }
                if let Some(state) = self.chatrooms.get_mut(&project_id) {
                    state.is_scrollbar_dragging = false;
                }
            }
            MouseEventKind::Down(MouseButton::Left) => {
                if let Some(state) = self.chatrooms.get_mut(&project_id) {
                    state.is_scrollbar_dragging = false;
                }
            }
            _ => {}
        }
    }

    /// True while the active room owns an in-progress scrollbar drag. The
    /// top-level mouse router uses this to retain the gesture outside the pane.
    pub fn is_chatroom_scrollbar_dragging(&self) -> bool {
        let RightPanelTarget::Chatroom { project_id } = self.right_panel_target else {
            return false;
        };
        self.chatrooms
            .get(&project_id)
            .is_some_and(|state| state.is_scrollbar_dragging)
    }

    /// Returns wrapped-line scroll limits for one cached room at the current
    /// responsive right-panel width.
    pub fn chatroom_scroll_metrics(
        &self,
        project_id: NodeId,
    ) -> Option<crate::chatroom_ui::ChatroomScrollMetrics> {
        let state = self.chatrooms.get(&project_id)?;
        Some(crate::chatroom_ui::scroll_metrics(
            self.layout.pane_area,
            &state.messages,
            state.scroll_from_newest,
        ))
    }

    /// Moves through history by rendered rows. Negative movement goes toward
    /// older messages; reaching the newest valid top re-enables live following.
    pub fn scroll_chatroom_by(&mut self, project_id: NodeId, direction: i32, lines: usize) {
        let Some(metrics) = self.chatroom_scroll_metrics(project_id) else {
            return;
        };
        let next_top = if direction < 0 {
            metrics.top.saturating_sub(lines)
        } else {
            metrics.top.saturating_add(lines).min(metrics.maximum_top)
        };
        self.set_chatroom_scroll_top(project_id, next_top, metrics.maximum_top);
    }

    /// Jumps to the oldest available wrapped row and disables live following
    /// whenever the room actually overflows.
    pub fn scroll_chatroom_to_top(&mut self, project_id: NodeId) {
        let Some(metrics) = self.chatroom_scroll_metrics(project_id) else {
            return;
        };
        self.set_chatroom_scroll_top(project_id, 0, metrics.maximum_top);
    }

    /// Returns to the live tail. A zero tail distance is the sole state that
    /// follows newly appended messages automatically.
    pub fn scroll_chatroom_to_bottom(&mut self, project_id: NodeId) {
        if let Some(state) = self.chatrooms.get_mut(&project_id) {
            state.scroll_from_newest = 0;
        }
    }

    /// Stores a bounded top row as its distance from the newest valid top.
    /// This representation makes "pinned to bottom" explicit and resize-safe.
    fn set_chatroom_scroll_top(&mut self, project_id: NodeId, top: usize, maximum_top: usize) {
        if let Some(state) = self.chatrooms.get_mut(&project_id) {
            state.scroll_from_newest = maximum_top.saturating_sub(top.min(maximum_top));
        }
    }

    /// Builds the participant list from the already server-confirmed pane
    /// tree. Chat authors are historical; this deliberately reports only
    /// currently live agent panes as active participants.
    pub fn chatroom_participants(&self, project_id: NodeId) -> Vec<String> {
        self.tree
            .all_ids()
            .filter(|pane_id| self.tree.project_ancestor(*pane_id) == Some(project_id))
            .filter_map(|pane_id| {
                let node = self.tree.get(pane_id)?;
                let NodeKind::Pane { status, .. } = &node.kind else {
                    return None;
                };
                match status {
                    PaneStatus::Agent(agent) => Some(format!(
                        "{} — {} ({:?})",
                        agent.class.label(),
                        node.name,
                        agent.activity()
                    )),
                    _ => None,
                }
            })
            .collect()
    }

    /// Activates the surviving sidebar row chosen after a close. Panes and
    /// split views reopen their right-panel content; ordinary containers and
    /// folder roots become the tree selection without changing expansion.
    pub(crate) fn activate_tree_successor(&mut self, node_id: NodeId) {
        let Some(node) = self.tree.get(node_id) else {
            return;
        };
        let is_split_view = node.is_split_view();
        let is_pane = node.is_pane();

        if is_split_view {
            self.show_split_view(node_id);
        } else if is_pane {
            self.focus_pane(node_id);
        } else {
            self.select_node(node_id);
            self.leave_pane_focus();
        }
    }

    fn layout_for_animation(&self, screen_area: Rect, tree_width: u16) -> UiLayout {
        let show_osm_attribution = self.animation_wants_attribution();
        UiLayout::from_screen_area_with_tree_width_and_attribution(
            screen_area,
            tree_width,
            show_osm_attribution,
        )
    }

    /// Updates the geometry shared by rendering, hit-testing, and pane
    /// sizing, and queues a `ResizePane` request for every terminal pane
    /// whose size actually changed.
    pub fn set_layout(&mut self, layout: UiLayout, resize_cause: PaneResizeCause) {
        if self.layout == layout {
            return;
        }
        self.layout = layout;
        self.resize_displayed_panes(resize_cause);

        // Markdown parsing and rasterization can be materially more
        // expensive than terminal sizing.  A sidebar-width animation emits
        // roughly eleven intermediate layouts, none of whose rendered
        // document can remain visible at its final width, so rebuild only
        // after the animation's final layout settles.
        let is_markdown_rebuild_deferred = self.is_layout_animating();

        for id in self.displayed_pane_ids() {
            let is_rendered_editor = matches!(
                self.panes.get(&id),
                Some(PaneRuntime::Editor(editor)) if editor.view_mode == EditorViewMode::Rendered
            );
            if is_rendered_editor && !is_markdown_rebuild_deferred {
                self.rebuild_rendered_markdown(id);
            }
        }
    }

    /// Recomputes geometry after the host terminal changes size while
    /// preserving the animation's current visible width.
    pub fn set_screen_area(&mut self, screen_area: Rect) {
        let layout =
            self.layout_for_animation(screen_area, self.tree_width_animation.current_width());
        self.set_layout(layout, PaneResizeCause::HostTerminal);
        self.tick_layout_animation(Instant::now());
    }

    /// Applies `ui` as this session's live settings: threads the change
    /// through to every runtime piece that isn't purely presentational --
    /// the tree-width animation's base width and the active color theme
    /// (`crate::theme::set`) both live outside `self.ui_settings` itself, so
    /// they need to be told explicitly rather than just reading the new
    /// value next frame. Called once at startup (`crate::run`, after
    /// `crate::config::load`) and again by every settings-screen control
    /// that changes a value (see `apply_and_persist_ui_settings`).
    pub fn apply_ui_settings(&mut self, ui: UiSettings) {
        if !ui.agent_debug_menu_enabled {
            if matches!(
                self.mode,
                Mode::AgentDebugLog(_) | Mode::AgentDebugSavePath(..)
            ) {
                self.mode = Mode::Normal;
            }
            // The save-path prompt stacks over its debug-log parent via
            // `push_modal_over`, and `ui::draw` renders every suspended
            // `modal_stack` layer (and treats its first entry as the root
            // mode). Resetting only `self.mode` would leave that suspended
            // `AgentDebugLog` painted behind everything with no input path
            // left to pop it, so the stack must drop those layers too.
            self.modal_stack.retain(|mode| {
                !matches!(mode, Mode::AgentDebugLog(_) | Mode::AgentDebugSavePath(..))
            });
            self.remove_agent_debug_action_from_terminal_menu();
        }
        self.ui_settings = ui.clone();
        let now = Instant::now();
        self.tree_width_animation.set_motion_enabled(
            matches!(ui.motion_level, crate::config::MotionLevel::Full),
            now,
        );
        if !matches!(ui.motion_level, crate::config::MotionLevel::Full) {
            self.tree_transitions = TreeTransitions::default();
        }
        let is_tree_active = self.is_tree_active();
        let resolved_width = ui
            .left_panel_sizing
            .resolved_width(self.layout.screen_area.width, is_tree_active);
        self.tree_width_animation.snap_to(resolved_width, now);
        theme::set(Theme::for_scheme(ui.color_scheme));
        let layout = self.layout_for_animation(
            self.layout.screen_area,
            self.tree_width_animation.current_width(),
        );
        self.set_layout(layout, PaneResizeCause::UserInterfaceSettings);
    }

    pub fn apply_terminal_settings(&mut self, settings: TerminalSettings) {
        self.terminal_settings = settings;
        for pane in self.panes.values_mut() {
            if let PaneRuntime::Terminal(view) = pane {
                view.set_scrollback_budget_mib(settings.scrollback_budget_mib);
            }
        }
        if let Some(parsing) = &self.terminal_parsing {
            parsing.set_budget_mib(settings.engine_memory_budget_mib);
        }
    }
    pub fn apply_editor_settings(&mut self, settings: EditorSettings) {
        self.editor_settings = settings;
        for pane in self.panes.values_mut() {
            if let PaneRuntime::Editor(editor) = pane {
                editor.apply_defaults(&settings);
            }
        }
    }
    pub fn apply_session_settings(&mut self, settings: SessionSettings) {
        self.session_settings = settings;
    }

    pub fn apply_git_settings(&mut self, settings: GitSettings) {
        self.git_settings = settings;
        self.git_settings_error = None;
    }

    pub fn apply_and_persist_git_settings(&mut self, settings: GitSettings) -> Result<(), String> {
        if let Err(error) = settings.validate() {
            self.git_settings_error = Some(error.clone());
            return Err(error);
        }
        if let Some(directory) = self.config_dir.clone() {
            self.enqueue_configuration(
                directory,
                crate::filesystem::configuration::ConfigurationChange::Git(settings.clone()),
                crate::filesystem::configurations::ConfigurationIntent::Plain {
                    label: "Git settings",
                    success: None,
                },
            )?;
        }
        self.git_settings = settings;
        self.git_settings_error = None;
        Ok(())
    }

    pub fn settings_adjust_git_row(&mut self, row: GitRow, direction: i32) {
        let mut settings = self.git_settings.clone();
        match row {
            GitRow::DefaultWhere => {
                settings.default_where = settings.default_where.stepped(direction)
            }
            GitRow::DefaultBase => settings.default_base = settings.default_base.stepped(direction),
            GitRow::BranchLine => settings.branch_line = settings.branch_line.stepped(direction),
            GitRow::DefaultClosePolicy => {
                settings.default_close_policy = settings.default_close_policy.stepped(direction)
            }
            GitRow::BranchPrefix => {
                self.settings_open_git_text_field(GitTextField::BranchPrefix);
                return;
            }
            GitRow::WorktreeLocationTemplate => {
                self.settings_open_git_text_field(GitTextField::WorktreeLocationTemplate);
                return;
            }
            GitRow::SetupCommand => {
                self.settings_open_git_text_field(GitTextField::SetupCommand);
                return;
            }
        }
        if let Err(error) = self.apply_and_persist_git_settings(settings) {
            self.status_message = Some(error);
        }
    }

    pub fn settings_open_git_text_field(&mut self, field: GitTextField) {
        let value = match field {
            GitTextField::BranchPrefix => &self.git_settings.branch_prefix,
            GitTextField::WorktreeLocationTemplate => &self.git_settings.worktree_location_template,
            GitTextField::SetupCommand => &self.git_settings.setup_command,
        };
        self.push_modal(Mode::GitSettingPrompt(field, TextPromptState::new(value)));
    }

    pub fn settings_commit_git_text_field(&mut self, field: GitTextField, value: String) {
        let mut settings = self.git_settings.clone();
        match field {
            GitTextField::BranchPrefix => settings.branch_prefix = value.trim().to_string(),
            GitTextField::WorktreeLocationTemplate => {
                settings.worktree_location_template = value.trim().to_string()
            }
            GitTextField::SetupCommand => settings.setup_command = value,
        }
        if let Err(error) = self.apply_and_persist_git_settings(settings) {
            self.status_message = Some(error);
        }
    }

