    #[test]
    fn terminal_activity_uses_fast_then_half_second_then_idle_maintenance() {
        let mut app = app();
        let pane_id = NodeId(73);
        let now = Instant::now();
        app.started_at = now;
        app.terminal_activity.record(pane_id, 0);

        assert_eq!(app.next_maintenance_delay(now), Duration::from_millis(90));

        app.started_at = now - Duration::from_millis(6_250);
        assert_eq!(app.next_maintenance_delay(now), Duration::from_millis(250));
        assert!(app.has_active_animation());

        app.started_at = now - Duration::from_millis(59_900);
        assert_eq!(app.next_maintenance_delay(now), Duration::from_millis(100));

        app.started_at = now - Duration::from_secs(60);
        assert_eq!(app.next_maintenance_delay(now), Duration::from_secs(1));
        assert!(!app.has_active_animation());
    }

    #[test]
    fn motion_off_suppresses_frame_wakes_but_keeps_terminal_activity_expiry() {
        let mut app = app();
        app.ui_settings.motion_level = crate::config::MotionLevel::Off;
        let group_id = app.tree.add_group(ROOT_ID, "agents").unwrap();
        let pane_id = app
            .tree
            .add_pane(group_id, "agent", PaneContentKind::Terminal)
            .unwrap();
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(AgentClass::Codex, AgentActivity::Working, None),
            )
            .unwrap();
        let now = Instant::now();
        app.started_at = now;

        for activity in [
            AgentActivity::Working,
            AgentActivity::WaitingBackground,
            AgentActivity::Done,
        ] {
            app.tree
                .set_pane_status(
                    pane_id,
                    PaneStatus::from_activity(AgentClass::Codex, activity, None),
                )
                .unwrap();

            let schedule = app.maintenance_schedule(now);
            assert_eq!(schedule.delay, Duration::from_secs(1), "{activity:?}");
            assert!(!schedule.was_animating, "{activity:?}");
        }

        app.terminal_activity.record(pane_id, 0);

        let fast_schedule = app.maintenance_schedule(now);
        assert_eq!(fast_schedule.delay, Duration::from_secs(5));
        assert!(!fast_schedule.was_animating);
        assert!(!app.has_active_animation());

        app.started_at = now - Duration::from_millis(6_250);
        let slow_schedule = app.maintenance_schedule(now);
        assert_eq!(slow_schedule.delay, Duration::from_secs(1));
        assert!(!slow_schedule.was_animating);

        app.started_at = now - Duration::from_millis(59_900);
        let expiry_schedule = app.maintenance_schedule(now);
        assert_eq!(expiry_schedule.delay, Duration::from_millis(100));
        assert!(!expiry_schedule.was_animating);

        app.started_at = now - Duration::from_secs(60);
        let idle_schedule = app.maintenance_schedule(now);
        assert_eq!(idle_schedule.delay, Duration::from_secs(1));
        assert!(!idle_schedule.was_animating);
    }

