    #[test]
    fn right_click_menu_offers_copy_selection_only_when_the_pane_has_one() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "shell", PaneContentKind::Terminal)
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new({
                let mut view = TerminalView::new(24, 80);
                view.feed(b"hello selection world");
                view
            })),
        );
        app.right_panel_target = RightPanelTarget::Pane { pane_id };
        app.focus = FocusTarget::Pane;
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        let viewport = app.pane_viewport(pane_id).unwrap();
        let position = Position::new(viewport.content_area.x + 3, viewport.content_area.y + 1);
        let right_click = MouseEvent {
            kind: MouseEventKind::Down(MouseButton::Right),
            column: position.x,
            row: position.y,
            modifiers: KeyModifiers::NONE,
        };

        app.handle_pane_mouse(right_click, position);
        let Mode::TerminalPaneContextMenu(menu) = std::mem::replace(&mut app.mode, Mode::Normal)
        else {
            panic!("right click should open the terminal menu");
        };
        assert!(!menu
            .actions
            .contains(&TerminalContextAction::CopySelectionToClipboard));
        assert_eq!(menu.selection_text, None);

        app.terminal_selection = Some(crate::terminal_selection::TerminalSelection {
            pane_id,
            anchor: crate::terminal_selection::SelectionPoint::new(0, 0),
            cursor: crate::terminal_selection::SelectionPoint::new(0, 4),
        });
        app.handle_pane_mouse(right_click, position);
        let Mode::TerminalPaneContextMenu(menu) = std::mem::replace(&mut app.mode, Mode::Normal)
        else {
            panic!("right click should open the terminal menu");
        };
        assert_eq!(
            menu.actions.first(),
            Some(&TerminalContextAction::CopySelectionToClipboard),
            "copy-selection should be the first action once the pane has one"
        );
        assert_eq!(menu.selection_text.as_deref(), Some("hello"));
    }

    #[test]
    fn agent_toolbar_actions_send_the_bytes_their_tooltip_promises() {
        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "claude", PaneContentKind::Terminal)
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new(TerminalView::new(24, 80))),
        );
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(AgentClass::Claude, AgentActivity::Working, None),
            )
            .unwrap();
        app.take_outbound_requests();

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::Compact);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::SubmitTerminalText {
                pane_id,
                text: "/compact".to_owned(),
                source: PromptSubmissionSource::ToolbarAction,
            }]
        );

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::Stop);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"\x1b".to_vec(),
                submission: None,
            }]
        );

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::Model(0));
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::SubmitTerminalText {
                pane_id,
                text: "/model haiku".to_owned(),
                source: PromptSubmissionSource::ToolbarAction,
            }]
        );

        // Auto -> Low -> Medium -> High -> XHigh -> Max -> Ultracode: six
        // clicks reach the one level that deliberately doesn't become a
        // slash command (see `EffortLevel::Ultracode`'s doc comment).
        for _ in 0..5 {
            app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CycleEffort);
            app.take_outbound_requests();
        }
        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CycleEffort);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"ultracode ".to_vec(),
                submission: None,
            }]
        );
    }

    #[test]
    fn smart_copy_freezes_the_visible_screen_and_accepts_a_unique_streamed_record() {
        let mut app = app();
        app.inference_settings.instructions.smart_copy = "Prioritize URLs {{literal}} & 🦀".into();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "codex", PaneContentKind::Terminal)
            .unwrap();
        let mut view = TerminalView::new(4, 40);
        view.feed(b"curl https://example.test/api\r\n");
        app.panes
            .insert(pane_id, PaneRuntime::Terminal(Box::new(view)));

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::SmartCopy);

        assert!(matches!(app.mode, Mode::SmartCopy));
        let request = app
            .take_pending_smart_copy_request()
            .expect("toolbar action should queue inference");
        assert!(request
            .request
            .system_prompt
            .contains("Prioritize URLs {{literal}} & 🦀"));
        assert_eq!(
            request.request.max_tokens,
            ilium_inference::UNKNOWN_MODEL_MAX_OUTPUT_TOKENS
        );
        assert!(request
            .request
            .user_prompt
            .contains("https://example.test/api"));

        let Some(PaneRuntime::Terminal(view)) = app.panes.get_mut(&pane_id) else {
            panic!("terminal pane should remain available");
        };
        view.feed(b"live output changed after capture\r\n");
        app.apply_smart_copy_worker_event(crate::smart_copy_workers::SmartCopyWorkerEvent {
            retention: None,
            generation: request.generation,
            pane_id,
            update: crate::smart_copy_workers::SmartCopyWorkerUpdate::JsonLine(
                r#"{"label":"curl","kind":"word","parts":[{"line":1,"from":"w1","through":"w1"}]}"#
                    .to_string(),
            ),
        });

        let session = app
            .smart_copy_session
            .as_ref()
            .expect("selection session should remain active");
        assert_eq!(session.candidates.len(), 3);
        assert!(session
            .candidates
            .iter()
            .any(|candidate| candidate.kind == "word" && candidate.text == "curl"));
        let paragraph = session
            .candidates
            .iter()
            .find(|candidate| candidate.kind == "paragraph")
            .expect("the pre-scan should retain the frozen paragraph");
        assert_eq!(paragraph.text, "curl https://example.test/api");
        assert!(!paragraph.text.contains("live output changed"));
    }

    fn codex_pane(app: &mut App) -> NodeId {
        let group = app.tree.add_group(ROOT_ID, "codex-work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "codex", PaneContentKind::Terminal)
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new(TerminalView::new(24, 80))),
        );
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(AgentClass::Codex, AgentActivity::Working, None),
            )
            .unwrap();
        app.take_outbound_requests();
        pane_id
    }

    #[test]
    fn codex_reasoning_level_stages_the_full_keystroke_sequence_across_ticks() {
        let mut app = app();
        let pane_id = codex_pane(&mut app);

        // Astra (index 1) at High (index 2): "/model", Enter, "2", "3".
        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CodexReasoningLevel(1, 2));
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"/model".to_vec(),
                submission: None,
            }]
        );

        let start = Instant::now();
        app.drain_pending_staged_keystrokes(start);
        assert!(
            app.take_outbound_requests().is_empty(),
            "the next stage isn't due until STAGED_KEYSTROKE_DELAY has elapsed"
        );

        let mut now = start + STAGED_KEYSTROKE_DELAY;
        app.drain_pending_staged_keystrokes(now);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"\r".to_vec(),
                submission: None,
            }]
        );

        now += STAGED_KEYSTROKE_DELAY;
        app.drain_pending_staged_keystrokes(now);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"2".to_vec(),
                submission: None,
            }]
        );

        now += STAGED_KEYSTROKE_DELAY;
        app.drain_pending_staged_keystrokes(now);
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"3".to_vec(),
                submission: None,
            }]
        );

        // Sequence is finished; a further drain does nothing.
        now += STAGED_KEYSTROKE_DELAY;
        app.drain_pending_staged_keystrokes(now);
        assert!(app.take_outbound_requests().is_empty());
    }

    #[test]
    fn codex_max_reasoning_level_adds_the_advanced_reasoning_stage() {
        let mut app = app();
        let pane_id = codex_pane(&mut app);

        // Sol (index 0) at Max (index 4): "/model", Enter, "1", "5", "1".
        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CodexReasoningLevel(0, 4));
        app.take_outbound_requests();
        let mut now = Instant::now();
        let mut stages = Vec::new();
        for _ in 0..4 {
            now += STAGED_KEYSTROKE_DELAY;
            app.drain_pending_staged_keystrokes(now);
            stages.extend(app.take_outbound_requests());
        }
        let bytes: Vec<Vec<u8>> = stages
            .into_iter()
            .map(|request| match request {
                ClientRequest::KeyInput { bytes, .. } => bytes,
                other => panic!("expected KeyInput, got {other:?}"),
            })
            .collect();
        assert_eq!(
            bytes,
            vec![b"\r".to_vec(), b"1".to_vec(), b"5".to_vec(), b"1".to_vec()]
        );
    }

    #[test]
    fn a_second_codex_reasoning_level_click_is_ignored_while_one_is_in_flight() {
        let mut app = app();
        let pane_id = codex_pane(&mut app);

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CodexReasoningLevel(0, 0));
        app.take_outbound_requests();

        // A second click before the first sequence finishes must not
        // interleave a fresh "/model" into the middle of the in-flight one.
        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::CodexReasoningLevel(1, 1));
        assert!(app.take_outbound_requests().is_empty());
    }

