    #[test]
    fn clicking_a_codex_tier_button_opens_its_submenu_then_a_level_click_sends_the_first_stage() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let mut app = app();
        let pane_id = codex_pane(&mut app);
        app.right_panel_target = RightPanelTarget::Pane { pane_id };
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        // Compact icons-only mode: with labels on (the default), Codex's
        // labeled center group is wider than this pane, and `button_rects`'
        // fit loop correctly drops the tier buttons from the right rather
        // than overlapping Close. This test is about submenu dispatch, not
        // narrow-toolbar degradation, so pin the compact mode it needs.
        app.ui_settings.show_toolbar_labels = false;
        app.agent_toolbar_latched_panes.insert(pane_id);
        app.resize_displayed_panes(PaneResizeCause::RightPanelPresentation);
        app.take_outbound_requests();

        let toolbar_area = app.pane_viewport(pane_id).unwrap().toolbar_area.unwrap();
        let toolbar_ctx = crate::agent_toolbar::ToolbarContext {
            provider: app.agent_toolbar_provider(pane_id),
            icons: &app.ui_settings.icons,
            effort: EffortLevel::Auto,
            show_labels: app.ui_settings.show_toolbar_labels,
            selection_enabled: app.ui_settings.terminal_text_selection_enabled,
        };
        let sol_rect = crate::agent_toolbar::button_rect_for(
            toolbar_area,
            toolbar_ctx,
            AgentToolbarAction::CodexModelTier(0),
        )
        .expect("Sol tier button should be in the toolbar");

        // Both clicks go through the real top-level dispatcher, not
        // `handle_pane_mouse` directly -- only that dispatcher checks
        // `app.mode` first and routes a click while the submenu is open to
        // `handle_agent_toolbar_model_submenu_mouse` instead of back into
        // ordinary pane-click handling.
        crate::mouse::handle_mouse_event(
            &mut app,
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: sol_rect.x,
                row: sol_rect.y,
                modifiers: KeyModifiers::NONE,
            },
        );

        let submenu_area = match &app.mode {
            Mode::AgentToolbarModelSubmenu(state) => {
                assert_eq!(state.tier_index, 0);
                assert_eq!(state.pane_id, pane_id);
                state.area
            }
            _ => panic!("clicking the Sol tier button should open its submenu"),
        };
        assert!(app.take_outbound_requests().is_empty());

        // Row 2 inside Sol's submenu (Low, Medium, High, ...) is "High".
        let level_row = submenu_area.y + 1 + 2;
        crate::mouse::handle_mouse_event(
            &mut app,
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: submenu_area.x + 1,
                row: level_row,
                modifiers: KeyModifiers::NONE,
            },
        );

        assert!(
            matches!(app.mode, Mode::Normal),
            "picking a level should close the submenu"
        );
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::KeyInput {
                pane_id,
                bytes: b"/model".to_vec(),
                submission: None,
            }]
        );
    }

    #[test]
    fn closing_the_agent_toolbar_hides_it_and_resizes_the_pty_back_up() {
        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "claude", PaneContentKind::Terminal)
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new(TerminalView::new(24, 80))),
        );
        app.right_panel_target = RightPanelTarget::Pane { pane_id };
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(AgentClass::Claude, AgentActivity::Working, None),
            )
            .unwrap();
        app.agent_toolbar_latched_panes.insert(pane_id);
        assert!(app.shows_agent_toolbar(pane_id));
        // Mirrors what `render_cache`'s `PaneStatusChanged` handler does
        // right after latching in production -- without it,
        // `requested_pane_sizes` would still hold the pre-toolbar height and
        // dedupe away the very resize this test is checking for.
        app.resize_displayed_panes(PaneResizeCause::RightPanelPresentation);
        let shrunk_height = app.pane_viewport(pane_id).unwrap().content_area.height;
        app.take_outbound_requests();

        app.execute_agent_toolbar_action(pane_id, AgentToolbarAction::Close);

        assert!(!app.ui_settings.agent_toolbar_enabled);
        assert!(!app.shows_agent_toolbar(pane_id));
        let restored = app.pane_viewport(pane_id).unwrap();
        assert_eq!(restored.toolbar_area, None);
        assert_eq!(restored.content_area.height, shrunk_height + 1);
        let resize = app
            .take_outbound_requests()
            .into_iter()
            .find_map(|request| match request {
                ClientRequest::ResizePane {
                    pane_id: resized_pane,
                    rows,
                    ..
                } if resized_pane == pane_id => Some(rows),
                _ => None,
            });
        assert_eq!(resize, Some(restored.content_area.height));
    }

    #[test]
    fn right_click_on_an_existing_file_offers_editor_and_external_open_actions() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let project = tempfile::tempdir().unwrap();
        let file_path = project.path().join("README.md");
        std::fs::write(&file_path, "# hi").unwrap();
        let resolved_path = project.path().join("./README.md");

        let mut app = App::new("test".to_string(), project.path().to_path_buf());
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "shell", PaneContentKind::Terminal)
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new({
                let mut view = TerminalView::new(24, 80);
                view.feed(b"see ./README.md for details");
                view
            })),
        );
        app.right_panel_target = RightPanelTarget::Pane { pane_id };
        app.focus = FocusTarget::Pane;
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        let viewport = app.pane_viewport(pane_id).unwrap();
        // "see ./README.md ..." -- column 4 lands inside the file token.
        let position = Position::new(viewport.content_area.x + 4, viewport.content_area.y);

        app.handle_pane_mouse(
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Right),
                column: position.x,
                row: position.y,
                modifiers: KeyModifiers::NONE,
            },
            position,
        );

        let Mode::TerminalPaneContextMenu(menu) = std::mem::replace(&mut app.mode, Mode::Normal)
        else {
            panic!("right click should open the terminal menu");
        };
        assert!(
            menu.actions.contains(&TerminalContextAction::OpenInEditor {
                path: resolved_path.clone()
            }),
            "menu should offer to open the existing file in an ilium editor: {:?}",
            menu.actions
        );
        assert!(
            menu.actions
                .contains(&TerminalContextAction::OpenExternally(
                    crate::open_target::OpenTarget::File(resolved_path.clone())
                )),
            "menu should offer to open the existing file the click resolved to: {:?}",
            menu.actions
        );
        app.execute_terminal_context_action(
            TerminalContextAction::OpenInEditor {
                path: resolved_path.clone(),
            },
            menu,
        );
        assert_eq!(
            app.take_outbound_requests()
                .into_iter()
                .find(|request| matches!(request, ClientRequest::NewPane { .. })),
            Some(ClientRequest::NewPane {
                parent_group: group,
                kind: ilium_ipc::NewPaneKind::Editor(resolved_path.clone()),
                working_directory: ilium_ipc::NewPaneWorkingDirectory::ProjectRoot,
            })
        );
        assert_eq!(
            app.status_message.as_deref(),
            Some(format!("Opening {} in editor", resolved_path.display()).as_str())
        );
    }

    /// Claude Code turns on xterm mouse tracking and Codex does not, so a
    /// right-click menu conditioned on that negotiation appeared in Codex
    /// panes and not Claude ones. The menu is the host's own affordance:
    /// it must open either way.
    #[test]
    fn right_click_opens_the_terminal_menu_even_when_the_agent_tracks_the_mouse() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "claude", PaneContentKind::Terminal)
            .unwrap();
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(AgentClass::Claude, AgentActivity::Working, None),
            )
            .unwrap();
        app.panes.insert(
            pane_id,
            PaneRuntime::Terminal(Box::new({
                let mut view = TerminalView::new(24, 80);
                // The exact modes Claude Code sets on startup: press/release,
                // button-motion, any-motion, SGR encoding.
                view.feed(b"\x1b[?1000h\x1b[?1002h\x1b[?1003h\x1b[?1006h");
                view.feed(b"first terminal line\r\nclicked terminal line");
                view
            })),
        );
        app.right_panel_target = RightPanelTarget::Pane { pane_id };
        app.focus = FocusTarget::Pane;
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        assert!(
            matches!(app.panes.get(&pane_id), Some(PaneRuntime::Terminal(view)) if view.wants_mouse_protocol()),
            "fixture must reproduce a pane whose agent tracks the mouse"
        );
        let viewport = app.pane_viewport(pane_id).unwrap();
        let position = Position::new(viewport.content_area.x + 3, viewport.content_area.y + 1);
        app.take_outbound_requests();

        app.handle_pane_mouse(
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Right),
                column: position.x,
                row: position.y,
                modifiers: KeyModifiers::NONE,
            },
            position,
        );

        let Mode::TerminalPaneContextMenu(menu) = &app.mode else {
            panic!("right click should open the terminal menu in a mouse-tracking agent pane");
        };
        assert_eq!(menu.pane_id, pane_id);
        assert_eq!(menu.source_line_text, "clicked terminal line");
        // The click must not also reach the agent as a button-2 report.
        assert!(
            app.take_outbound_requests()
                .iter()
                .all(|request| !matches!(request, ClientRequest::MouseInput { .. })),
            "the host consumed this right click, so nothing should be forwarded to the pty"
        );
    }

    #[test]
    fn split_terminal_menu_pastes_the_live_source_screen_into_an_adjacent_terminal() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let source_pane_id = app
            .tree
            .add_pane(group, "source", PaneContentKind::Terminal)
            .unwrap();
        let destination_pane_id = app
            .tree
            .add_pane(group, "destination", PaneContentKind::Terminal)
            .unwrap();
        let split_id = app
            .tree
            .create_split_view(
                group,
                "split",
                SplitOrientation::Vertical,
                &[source_pane_id, destination_pane_id],
            )
            .unwrap();
        app.tree
            .set_pane_status(
                destination_pane_id,
                PaneStatus::from_activity(AgentClass::Codex, AgentActivity::Working, None),
            )
            .unwrap();
        let mut source_view = TerminalView::new(12, 40);
        source_view.feed(b"screen contents to transfer");
        let mut destination_view = TerminalView::new(12, 40);
        destination_view.feed(b"\x1b[?2004h");
        app.panes
            .insert(source_pane_id, PaneRuntime::Terminal(Box::new(source_view)));
        app.panes.insert(
            destination_pane_id,
            PaneRuntime::Terminal(Box::new(destination_view)),
        );
        app.right_panel_target = RightPanelTarget::SplitView {
            split_id,
            active_pane_id: Some(source_pane_id),
        };
        app.focus = FocusTarget::Pane;
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        let source_viewport = app.pane_viewport(source_pane_id).unwrap();
        let position = Position::new(
            source_viewport.content_area.x + 3,
            source_viewport.content_area.y + 1,
        );
        let expected_screen = match app.panes.get(&source_pane_id) {
            Some(PaneRuntime::Terminal(view)) => view.with_screen(|screen| screen.contents()),
            _ => panic!("source terminal should remain available"),
        };
        app.take_outbound_requests();

        app.handle_pane_mouse(
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Right),
                column: position.x,
                row: position.y,
                modifiers: KeyModifiers::NONE,
            },
            position,
        );
        let Mode::TerminalPaneContextMenu(menu) = std::mem::replace(&mut app.mode, Mode::Normal)
        else {
            panic!("right click should open the terminal menu");
        };
        let action = menu
            .actions
            .iter()
            .find(|action| {
                matches!(
                    action,
                    TerminalContextAction::PasteScreenInto {
                        destination_pane_id: target,
                        direction: split_layout::PaneDirection::Right,
                        ..
                    } if *target == destination_pane_id
                )
            })
            .cloned()
            .expect("adjacent destination should have a screen-transfer action");
        assert_eq!(
            action.label(),
            "Paste screen into Codex agent on the right".to_string()
        );

        app.execute_terminal_context_action(action, menu);

        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::UserKeyInput {
                pane_id: destination_pane_id,
                bytes: encode_bracketed_paste(&expected_screen),
                submission: None,
                prompt_epoch: None,
            }]
        );
    }

    #[test]
    fn split_separator_transfer_control_pastes_only_from_its_adjacent_source() {
        use crossterm::event::{KeyModifiers, MouseButton, MouseEvent, MouseEventKind};

        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let source_pane_id = app
            .tree
            .add_pane(group, "source", PaneContentKind::Terminal)
            .unwrap();
        let destination_pane_id = app
            .tree
            .add_pane(group, "destination", PaneContentKind::Terminal)
            .unwrap();
        let split_id = app
            .tree
            .create_split_view(
                group,
                "split",
                SplitOrientation::Horizontal,
                &[source_pane_id, destination_pane_id],
            )
            .unwrap();
        let mut source_view = TerminalView::new(12, 40);
        source_view.feed(b"send downward");
        app.panes
            .insert(source_pane_id, PaneRuntime::Terminal(Box::new(source_view)));
        app.panes.insert(
            destination_pane_id,
            PaneRuntime::Terminal(Box::new(TerminalView::new(12, 40))),
        );
        app.right_panel_target = RightPanelTarget::SplitView {
            split_id,
            active_pane_id: Some(source_pane_id),
        };
        app.set_screen_area(Rect::new(0, 0, 120, 40));
        let transfer = app
            .screen_transfers()
            .into_iter()
            .find(|transfer| {
                transfer.source_pane_id == source_pane_id
                    && transfer.destination_pane_id == destination_pane_id
                    && transfer.direction == split_layout::PaneDirection::Down
            })
            .expect("top-to-bottom terminal separator should be actionable");
        let expected_screen = match app.panes.get(&source_pane_id) {
            Some(PaneRuntime::Terminal(view)) => view.with_screen(|screen| screen.contents()),
            _ => panic!("source terminal should remain available"),
        };
        app.take_outbound_requests();
        let position = Position::new(transfer.control_area.x, transfer.control_area.y);

        app.handle_pane_mouse(
            MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: position.x,
                row: position.y,
                modifiers: KeyModifiers::NONE,
            },
            position,
        );

        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::UserKeyInput {
                pane_id: destination_pane_id,
                bytes: expected_screen.into_bytes(),
                submission: None,
                prompt_epoch: None,
            }]
        );
        assert_eq!(
            app.status_message.as_deref(),
            Some("Screen pasted into terminal below")
        );
    }

    #[test]
    fn opening_debug_log_fetches_retained_history_before_using_incremental_replay() {
        let mut app = app();
        let group = app.tree.add_group(ROOT_ID, "work").unwrap();
        let pane_id = app
            .tree
            .add_pane(group, "claude", PaneContentKind::Terminal)
            .unwrap();
        app.tree
            .set_pane_status(
                pane_id,
                PaneStatus::from_activity(
                    AgentClass::Claude,
                    AgentActivity::WaitingApproval,
                    Some(ilium_core::GoalState::Active),
                ),
            )
            .unwrap();
        app.ui_settings.agent_debug_menu_enabled = true;
        app.agent_debug_logs.insert(
            pane_id,
            AgentDebugLogCache {
                through_sequence: 41,
                ..AgentDebugLogCache::default()
            },
        );

        app.open_agent_debug_log(pane_id);

        assert!(matches!(
            app.mode,
            Mode::AgentDebugLog(AgentDebugLogViewState {
                pane_id: target,
                scroll_position: AgentDebugLogScrollPosition::FromNewest(0),
            }) if target == pane_id
        ));
        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::GetPaneDebugLog {
                pane_id,
                after_sequence: None,
            }]
        );

        app.agent_debug_logs
            .get_mut(&pane_id)
            .unwrap()
            .has_loaded_retained_history = true;
        app.open_agent_debug_log(pane_id);

        assert_eq!(
            app.take_outbound_requests(),
            vec![ClientRequest::GetPaneDebugLog {
                pane_id,
                after_sequence: Some(41),
            }]
        );
    }

